window.chimeraSearchIndex = [{"p":"index.html","k":"page","t":"Home","g":"Home","x":"chimera is a library for building static websites in Luwu. It turns pages made of classes like Paragraph , Menu and CodeBlock into ready-to-publish HTML. Light and dark themes, Catppuccin flavors and a theme switcher Menus, tabs, toggles, cards and layouts, all styled by the theme Luwu, Luau and Lua highlighted at build time, with squiggles and hovers Typed styles that the Luwu analyzer checks as you write them HTML that roundtrips into the same objects, to keep editing in Luwu Get started Source on GitHub"},{"p":"index.html#a-quick-look","k":"section","c":"curl -fsSL https://example.com/install.sh | sh winget install example const install = Tabs({ Tab(\"Linux\", CodeBlock(\"curl -fsSL https://example.com/install.sh | sh\", \"bash\")), Tab(\"Windows\", CodeBlock(\"winget install example\", \"shell\")), }) const changes = Paragraph(\"Saves load twice as fast. Old saves still work.\") const notes = Section { h3(\"Version 2.0\"), Paragraph(\"Released October 2026.\"), install, Row({ Toggle(\"What changed?\", changes), Link(\"Full changelog\", \"#\") }):align(\"center\"), changes:hidden(), }","t":"A quick look","g":"Home","x":"Here's a small release notes section with the code that builds it underneath. The tabs, the \"What changed?\" toggle and all of the colors come with chimera and follow whichever theme you pick, and you didn't have to write any CSS or JavaScript for them. Version 2.0 Released October 2026. What changed? Full changelog Saves load twice as fast. Old saves still work."},{"p":"index.html#checked-by-default","k":"section","c":"const .{ elements.{ Paragraph }, components.{ Card } } = require(\"@chimera\") const note = Card(\"Heads up\", Paragraph(\"Back up your saves.\")) :style({ padding = \"1rx\", display = \"flexx\" })","t":"Checked by default","g":"Home","x":"Luwu type checks in strict mode by default, and chimera describes CSS values with Luwu's type function validators. The analyzer checks every style you write against them. A wrong unit or a misspelled keyword shows up in your editor before you ever build the page. Hover the squiggles: Both messages come straight from luwu-analyze ."},{"p":"index.html#where-to-go-next","k":"section","t":"Where to go next","g":"Home","x":"Sites and pages Pages, nested folders, links and tables of contents. Components Menus, dropdowns, tabs, toggles, cards and a theme switcher. Code Luwu highlighting at build time, squiggles and hovers. Theming Light and dark defaults, Catppuccin, and themes of your own. Styling Typed CSS that reads theme tokens. Custom components Your own components, written once as classes. This site is built with chimera. Its source is examples/site.luwu ."},{"p":"guide.html","k":"page","t":"Guide","g":"Guide","x":"How to build static websites with chimera"},{"p":"guide.html#install","k":"section","c":"git clone https://github.com/seal-runtime/chimera libraries/chimera { \"aliases\": { \"chimera\": \"./libraries/chimera\" } }","t":"Install","g":"Guide","x":"chimera runs on seal, a runtime for Luwu. You need a seal built with Luwu support: seal 0.9, from the luwu-classes branch. Clone chimera into your project: Then point an alias at it in your project's .luaurc , and require(\"@chimera\") will find it:"},{"p":"guide.html#your-first-page","k":"section","c":"const fs = require(\"@std/fs\") const chimera = require(\"@chimera\") const .{ Document, elements.{ Heading, Paragraph, Main, Link } } = chimera const .{ h1 } = Heading const page = Document(\"Hello\") :add(Main { h1(\"Hello\"), Paragraph({ \"Built with \", Link(\"chimera\", \"https://github.com/seal-runtime/chimera\"), \".\" }), }) fs.writefile(\"hello.html\", page:to_html(true)) const hello = Main { h1(\"Hello\"), Paragraph({ \"Built with \", Link(\"chimera\", \"https://github.com/seal-runtime/chimera\"), \".\" }), }","t":"Your first page","g":"Guide","x":"A Document is one HTML page. Add elements to it, render it with to_html , and write the result with seal's fs library: Run it with seal ./hello.luwu and the page's body looks like this: Built with chimera . You didn't write any CSS, but the page is styled and follows the reader's light or dark mode. to_html(true) indents the HTML for reading. Leave out true for compact output."},{"p":"guide.html#your-first-site","k":"section","c":"const .{ site.{ Site, Page } } = chimera const home = Page(\"Home\", { h1(\"Hello\"), Paragraph(\"Welcome!\") }, \"index.html\") const notes = Page(\"Notes\", { h1(\"Notes\"), Paragraph(\"Things I learned.\") }) Site(\"My site\") :add_page(home, notes) :build(\"out\")","t":"Your first site","g":"Guide","x":"Once you have more than one page, use a Site . It renders every page with the same header, footer and themes, and the default header already has a menu of your pages and a theme switcher. That writes out/index.html and out/notes.html . Sites and pages covers nested pages, links between them and tables of contents."},{"p":"guide.html#what-s-where","k":"section","t":"What's where","g":"Guide","x":"chimera groups its classes by what they're for. Destructure the ones you need from require(\"@chimera\") : Module What's in it Guide elements One class per HTML tag Elements components Menus, tabs, cards, code blocks, layouts Components , Layout , Code style Typed CSS, colors and theme tokens Styling themes Light, Dark and the Catppuccin flavors Theming site Sites, pages and the links between them Sites and pages serde Markdown and JSON, in and out Markdown and JSON top level Traits for your own elements, Document, Parser Custom components , Parsing HTML"},{"p":"guide/sites-and-pages.html","k":"page","t":"Sites and pages","g":"Sites and pages","x":"A documentation site with 30 pages repeats its header, footer and theme list 30 times, and sooner or later one copy falls out of date. In chimera you set those parts once on a Site and give each Page only its own content."},{"p":"guide/sites-and-pages.html#pages","k":"section","c":"const home = Page(\"Home\", { h1(\"Welcome\"), Paragraph(\"Start here.\") }, \"index.html\") const faq = Page(\"FAQ\", h1(\"FAQ\")) faq:add(h2(\"Is it free?\"), Paragraph(\"Yes.\"))","t":"Pages","g":"Sites and pages","x":"A Page takes a title, its content and an optional file name. Without one, the file is named after the title in lowercase with dashes: Page(\"Getting started\") writes getting-started.html . add appends more content later."},{"p":"guide/sites-and-pages.html#nested-pages","k":"section","c":"const docs = Page(\"Docs\", h1(\"Docs\"), \"docs/index.html\") :add_page( Page(\"Install\"), -- docs/install.html Page(\"Themes\") -- docs/themes.html ) const guide = Page(\"Guide\") -- guide.html :add_page(Page(\"Setup\")) -- guide/setup.html","t":"Nested pages","g":"Sites and pages","x":"Pages can hold pages of their own, and those go in a folder named after their parent. A parent called index.html shares its folder with its children instead: This page is guide/sites-and-pages.html , a child of the Guide. Nested pages get breadcrumbs above their content like the ones at the top of this page, and site:breadcrumbs(false) turns them off."},{"p":"guide/sites-and-pages.html#links-between-pages","k":"section","c":"PageLink(faq) -- \"FAQ\" PageLink(docs, \"Read the docs\") PageLink(\"docs/install.html\") -- a path from the site's root","t":"Links between pages","g":"Sites and pages","x":"PageLink points at a Page object rather than a path. When the page renders, the link works out the relative path from its own folder. Moving a page never breaks the links to it. The text defaults to the page's title: Because every link is relative, the built site also works from disk over file:// . You don't need a server to check it."},{"p":"guide/sites-and-pages.html#tables-of-contents","k":"section","c":"TableOfContents() -- this page's h2 and h3 headings, and its subpages TableOfContents(\"page\", 2) -- h2 headings only TableOfContents(\"site\", 3, \"Pages\") -- every page of the site, for a sidebar","t":"Tables of contents","g":"Sites and pages","x":"TableOfContents() lists its page's headings and the pages under it. It's built when the page renders, from whatever the page holds at that moment. The box at the top of this page is one; on wide screens it moves into a column beside the text."},{"p":"guide/sites-and-pages.html#the-site","k":"section","c":"const site = Site(\"My docs\") :describe(\"Guides and reference for my library\") :default_dark_theme(catppuccin.Mocha) :default_light_theme(catppuccin.Latte) :add_page(home, docs, faq) for _, path in site:build(\"out\") do print(`wrote {path}`) end","t":"The site","g":"Sites and pages","x":"A Site holds the top-level pages and everything they share. build writes them all, creating folders as it goes, and returns the paths it wrote: Two pages with the same path are an error rather than a silent overwrite. describe sets the summary search engines show, and a page can override it with its own describe ."},{"p":"guide/sites-and-pages.html#header-footer-and-sidebar","k":"section","c":"site :header(Header { Menu { PageLink(home, \"My docs\"), PageLink(docs), ThemeSwitcher() } }) :footer(none) :sidebar(TableOfContents(\"site\", 2, \"Pages\")) const footer = SiteFooter() :link_column(\"Docs\", { Link(\"Install\", \"#\"), Link(\"Themes\", \"#\") }) :link_column(\"Community\", { Link(\"Discord\", \"#\"), Link(\"GitHub\", \"#\") }) :copyright(\"Ada Lovelace\", \"Built with chimera.\")","t":"Header, footer and sidebar","g":"Sites and pages","x":"Unless you say otherwise, every page gets a header with a menu of the top-level pages and a theme switcher, plus a footer with the site's copyright. Pass your own to replace either one, or none to leave it out: SiteFooter builds a footer like this site's with link columns, a copyright line and legal links: Docs Install Themes Community Discord GitHub © 2026 Ada Lovelace. Built with chimera."},{"p":"guide/sites-and-pages.html#search","k":"section","c":"site:search()","t":"Search","g":"Sites and pages","x":"Readers of an API reference usually know a name, or half of one. They remember readFileSync but type read file , or they misspell it raedfilesync on the way. site:search() puts a box in the header that finds pages, sections and anything your own elements add while the reader types. It needs no server and works over file:// too: build writes the index the box searches, search-index.js , next to the pages. A site with its own header adds a Search() to it instead, and the index gets written all the same. Results show up under the box grouped by page, with the matching words marked. Arrow keys move through them and Enter opens one, and / or Ctrl+K jumps to the box from anywhere on the page."},{"p":"guide/sites-and-pages.html#how-it-matches","k":"section","c":"site:search(Search() :matchers({ Exact(200), Prefix(), Words(), Typos(25, 1) }) :weigh({ page = 0 }) )","t":"How it matches","g":"Sites and pages","x":"Every word of a query has to match somewhere in an entry: its title, its keywords, the title of its page or its text. Each word is tried several ways, and the best one counts: Exact : the whole name, or the part after its last dot, so readfile finds fs.readfile . Prefix : the start of a name, like fs.read . Words : names split the way programmers write them. readFileSync , read_file_sync and ReadFileSync all have the words read, file and sync, so read sync and http server find them. Initials : the first letter of each word, so rfs finds readFileSync and gcd finds get_current_dir . Substring : anywhere inside a name, so lines finds splitlines . Typos : a name within one or two typos, so splitlnies finds splitlines . Words under four letters allow none, which keeps os from finding fs . FullText : words in an entry's text and code samples, so utf8 finds the section that explains encodings even when its title doesn't say so. Prose counts more than code, and a query that appears word for word ranks higher. A query with capital letters ranks names written in the same case higher. Pass Search your own list of matchers to drop some or change how much each one counts. A matcher left out nev"},{"p":"guide/sites-and-pages.html#what-it-shows","k":"section","c":"Search() :placeholder(\"Search the API\") :kinds({ \"function\", \"type\" }) :limit(5) :min_score(20) :snippets(false) :group_by_page(false) :shortcut(\"s\")","t":"What it shows","g":"Sites and pages","x":"An API reference's search might show functions only, five at a time, without the text around each match. These settings cover that: Pages are the kind \"page\" and their sections are \"section\" . Other kinds come from your own elements."},{"p":"guide/sites-and-pages.html#your-own-entries","k":"section","c":"class ApiFunction implements Component function tag(): string return \"div\" end name = \"\" summary = \"\" function __init(self, name: string?, summary: string?) self.name = name or \"\" self.summary = summary or \"\" self:id((string.gsub(self.name, \"%W+\", \"-\"))) end function search_entries(self): { SearchEntry }? return { { kind = \"function\", title = self.name, anchor = self:get_id(), text = self.summary, keywords = { \"read\" }, }, } end end","t":"Your own entries","g":"Sites and pages","x":"An element that stands for something readers search for, like a function in a reference, says so in search_entries . The index adds its entries and skips its children. Give the element its id before the page renders so the result has somewhere to land:"},{"p":"guide/sites-and-pages.html#your-own-matchers","k":"section","c":"class Suffix(weight: number = 30) implements Matcher function source(self): string? return [=[ function (term, field) { return field.lower.endsWith(term.lower) ? 1 : 0; } ]=] end end Matcher.register(Suffix) site:search(Search():matchers({ Exact(), Prefix(), Suffix() }))","t":"Your own matchers","g":"Sites and pages","x":"Matching runs in the reader's browser, so a matcher of your own is a class with a little JavaScript. source returns a function that scores a query word against a name from 0 to 1. Register the class so parsed pages find it again:"},{"p":"guide/sites-and-pages.html#per-page-changes","k":"section","c":"site:customize(function(document, page) document:link_stylesheet(\"https://fonts.googleapis.com/css2?family=Inter\") if page.title == \"Home\" then document:describe(\"My library: fast, typed and small\") end end)","t":"Per-page changes","g":"Sites and pages","x":"For anything the site doesn't set itself, customize runs a function on each page's Document just before it's written: chimera only writes pages. Copy images and other files into the output folder yourself with fs.copy ."},{"p":"guide/elements.html","k":"page","t":"Elements","g":"Elements","x":"Elements are classes that correspond to specific HTML tags: Paragraph is <p> , UnorderedList is <ul> , Link is <a> and Image is <img> . All of them live in chimera.elements and are named after what the tag is rather than its abbreviation."},{"p":"guide/elements.html#content","k":"section","c":"Paragraph(\"Plain text\") Paragraph({ \"Mixed \", Strong(\"content\"), \" and numbers: \", 42 }) Paragraph({ \"Hello\", if signed_in then Strong(\" again\") else none })","t":"Content","g":"Elements","x":"An element's content can be a string, a number, another element or a list of any of those. When an item is optional, put none in its place: Text is always escaped: Paragraph(\"<b>\") shows the characters instead of bold text."},{"p":"guide/elements.html#text","k":"section","c":"const text = Div { h3(\"Release notes\"), Paragraph({ \"Version 2 is \", Strong(\"twice as fast\"), \" and \", Emphasis(\"much\"), \" smaller. Run \", Code(\"seal update\", \"bash\"), \" or read the \", Link(\"changelog\", \"https://example.com\"):new_tab(), \".\", }), BlockQuote(Paragraph(\"Upgrading took me five minutes.\")), Small(\"Released October 2026.\"), }","t":"Text","g":"Elements","x":"Release notes Version 2 is twice as fast and much smaller. Run seal update or read the changelog . Upgrading took me five minutes. Released October 2026. Headings have six levels, from Heading.h1 to Heading.h6 . Most pages destructure the ones they use with const .{ h1, h2 } = Heading ."},{"p":"guide/elements.html#lists","k":"section","c":"const lists = Div { UnorderedList({ \"Milk\", \"Eggs\", \"Flour\" }), OrderedList({ \"Preheat the oven\", \"Mix everything\", \"Bake for 25 minutes\" }), }","t":"Lists","g":"Elements","x":"Milk Eggs Flour Preheat the oven Mix everything Bake for 25 minutes Lists take strings or ListItem s, and a list item can hold any content. OrderedList:start(5) starts the count at 5."},{"p":"guide/elements.html#tables","k":"section","c":"const header = Table.header() :column(\"Cat\") :column(\"Age\") :column(\"Favorite toy\") const cat = Table.row_for(header) const cats = Table(header) :row(cat(\"Nyla\", 3, \"Feather wand\")) :row(cat(\"Taz\", 14, \"Cardboard box\")) :row({ Cat = \"Oreo\", Age = 1, [\"Favorite toy\"] = \"Your shoelaces\" }) :table_style({ striped = true })","t":"Tables","g":"Elements","x":"A table's columns are part of its type, and the analyzer checks every row against them. A misspelled or missing column is an error. row_for makes a function that builds rows from values in column order: Cat Age Favorite toy Nyla 3 Feather wand Taz 14 Cardboard box Oreo 1 Your shoelaces Besides stripes, table_style can highlight the row under the pointer with hover = true . Pass bold_header = false for plain headings."},{"p":"guide/elements.html#details","k":"section","c":"const faq = Details( \"Does chimera need JavaScript?\", Paragraph(\"Only for the theme switcher, tabs and toggles. Pages read fine without it.\") )","t":"Details","g":"Elements","x":"Details shows a summary that opens to reveal the rest without any JavaScript: Does chimera need JavaScript? Only for the theme switcher, tabs and toggles. Pages read fine without it."},{"p":"guide/elements.html#forms","k":"section","c":"const signup = Form(Column({ Label(\"Email\", \"email\"), Input(\"email\", \"email\") :id(\"email\") :placeholder(\"you@example.com\") :required(), Label(\"Plan\", \"plan\"), Select(\"plan\", { \"Free\", \"Pro\", \"Team\" }):id(\"plan\"), Button(\"Sign up\", \"submit\"), }):gap(\"0.5rem\"), \"/signup\", \"post\")","t":"Forms","g":"Elements","x":"Email Plan Sign up A static site has no server of its own to receive forms. Point action at a form service, or handle the submit event in a script."},{"p":"guide/elements.html#attributes-classes-and-events","k":"section","c":"Link(\"Docs\", \"/docs\") :id(\"docs-link\") :attr(\"title\", \"Read the docs\") :data(\"section\", \"top\") -- data-section=\"top\" :add_style_class(\"button\", \"large\") :on(\"click\", \"console.log('clicked')\")","t":"Attributes, classes and events","g":"Elements","x":"Every element shares the same chainable methods for attributes, classes and events: hidden() hides an element until a script shows it. When a chain needs a step that isn't a method, tap(function(element) ... end) runs your function and carries on. For a tag chimera has no class for, use Tag : Tag(\"dialog\", Paragraph(\"Sure?\")) ."},{"p":"guide/elements.html#all-elements","k":"section","t":"All elements","g":"Elements","x":"Class Tag Div, Section, Article, Aside, Main div section article aside main Header, Footer, Navigation header footer nav Heading h1–h6 Paragraph, Span, Strong, Emphasis, Small p span strong em small BlockQuote, Preformatted blockquote pre Link, Image, Figure, FigureCaption a img figure figcaption LineBreak, HorizontalRule br hr UnorderedList, OrderedList, ListItem ul ol li Table table Details, Summary details summary Form, Label, Input, TextArea, Select, Option, Button form label input textarea select option button"},{"p":"guide/layout.html","k":"page","t":"Layout","g":"Layout","x":"Most of a page's layout comes down to a row of buttons, a column of links or a grid of cards. chimera has a class for each that takes its spacing from the theme."},{"p":"guide/layout.html#rows","k":"section","c":"const actions = Row({ Button(\"Save\"), Button(\"Discard\") }):justify(\"end\")","t":"Rows","g":"Layout","x":"Row lays its children out left to right and wraps them when they run out of room: Save Discard"},{"p":"guide/layout.html#grids","k":"section","c":"const plans = Grid({ Card(\"Free\", Paragraph(\"One site, community support.\")), Card(\"Pro\", Paragraph(\"Ten sites and a custom domain.\")), Card(\"Team\", Paragraph(\"Unlimited sites and shared themes.\")), }, \"12rem\")","t":"Grids","g":"Layout","x":"Grid fits as many columns as it can, each at least as wide as you ask for. Make the window narrower and the cards below will stack: Free One site, community support. Pro Ten sites and a custom domain. Team Unlimited sites and shared themes."},{"p":"guide/layout.html#columns","k":"section","c":"const contact = Column({ Link(\"ada@example.com\", \"mailto:ada@example.com\"), Link(\"Discord\", \"https://discord.gg/example\"), Small(\"Replies within a day.\"), }):gap(\"0.25rem\")","t":"Columns","g":"Layout","x":"Column stacks its children top to bottom: ada@example.com Discord Replies within a day."},{"p":"guide/layout.html#arranging-any-container","k":"section","c":"const bar = Footer({ Small(\"© 2026 Ada\"), Row({ Link(\"Privacy\", \"#\"), Link(\"Terms\", \"#\") }) }) :row() :justify(\"space-between\") :align(\"center\") class Toolbar implements Component, Layout function tag(): string return \"div\" end function __init(self, content: Content?) self :add(content) :row() :gap(\"0.5rem\") end end","t":"Arranging any container","g":"Layout","x":"Row , Column and Grid are only Div s that start out arranged. Every built-in container has the same methods: row() , column() , grid(min_width) , gap(size) , wrap() , align(alignment) and justify(distribution) . © 2026 Ada Privacy Terms Alignments and sizes are typed like every other style: the analyzer reports justify(\"space-betwen\") as a typo and gap(\"1rx\") as an unknown unit. Your own containers get the same methods when they implement Layout (see Custom components ):"},{"p":"guide/components.html","k":"page","t":"Components","g":"Components","x":"Components are ready-made custom elements provided by chimera. These include Menu , Dropdown , ThemeSwitcher , Card , Toggle and Tabs , along with layouts, code blocks and site navigation. Each one brings its own HTML, CSS and script, is styled by the theme and works on small screens. They live in chimera.components ."},{"p":"guide/components.html#menu","k":"section","c":"const menu = Menu { Link(\"Home\", \"#\"), Link(\"Blog\", \"#\"), Dropdown(\"Projects\", { Link(\"chimera\", \"#\"), Link(\"seal\", \"#\"), Link(\"Luwu\", \"#\") }), ThemeSwitcher(), }","t":"Menu","g":"Components","x":"Menu is a navigation bar whose links fold behind a menu button on narrow screens. Inside it, a Dropdown opens a list of links without any JavaScript: Home Blog Projects chimera seal Luwu"},{"p":"guide/components.html#theme-switcher","k":"section","t":"Theme switcher","g":"Components","x":"ThemeSwitcher() lists every theme the page offers, each with a swatch of its colors, like the one in the menu above. The reader's pick is saved and follows them from page to page. Theming explains how to choose the themes it lists."},{"p":"guide/components.html#cards","k":"section","c":"const features = Grid({ Card(\"Offline\", Paragraph(\"Pages work from a USB stick. No server needed.\")), Card(\"Small\", Paragraph(\"A page like this one is about 60 KB, or 12 KB compressed.\")), }, \"14rem\")","t":"Cards","g":"Components","x":"Card is a raised box with an optional title: Offline Pages work from a USB stick. No server needed. Small A page like this one is about 60 KB, or 12 KB compressed."},{"p":"guide/components.html#toggles","k":"section","c":"const spoiler = Paragraph(\"The butler did it.\") const reveal = Div { Toggle(\"Show the ending\", spoiler), spoiler:hidden() }","t":"Toggles","g":"Components","x":"Toggle is a button that shows and hides another element: Show the ending The butler did it. The target can be an element or an element's id. Call hidden() on it to start it out hidden."},{"p":"guide/components.html#tabs","k":"section","c":"curl -fsSL https://example.com/install.sh | sh winget install example brew install example const install = Tabs({ Tab(\"Linux\", CodeBlock(\"curl -fsSL https://example.com/install.sh | sh\", \"bash\")), Tab(\"Windows\", CodeBlock(\"winget install example\", \"shell\")), Tab(\"macOS\", CodeBlock(\"brew install example\", \"bash\")), })","t":"Tabs","g":"Components","x":"Tabs shows one panel at a time with a row of tabs to switch between them: The first tab starts selected unless select(\"Windows\") picks another. Several Tabs on one page each switch on their own."},{"p":"guide/components.html#more","k":"section","t":"More","g":"Components","x":"SiteFooter , TableOfContents and Breadcrumbs are in Sites and pages . CodeBlock and Code are in Code . Row , Column and Grid are in Layout . If none of them fit, write your own: a component is a class you can write in a few lines. See Custom components ."},{"p":"guide/code.html","k":"page","t":"Code","g":"Code","x":"Documentation for a library is mostly code. chimera highlights Luwu, Luau and Lua while it builds the page. Readers download no highlighting script, and the colors follow whichever theme they picked. Squiggles and hovers then explain the code the way an editor would."},{"p":"guide/code.html#code-blocks","k":"section","c":"const function greet(name: string, greeting = \"Hello\") print(`{greeting}, {name}!`) end const greet = CodeBlock([==[ const function greet(name: string, greeting = \"Hello\") print(`{greeting}, {name}!`) end ]==]) :line_numbers() :copyable()","t":"Code blocks","g":"Code","x":"copyable() adds the copy button in the corner, and line_numbers() adds the gutter. Selecting the code never picks up the numbers."},{"p":"guide/code.html#inline-code","k":"section","c":"const tip = Paragraph({ \"Call \", Code(\"site:build(\\\"out\\\")\"), \" to write every page.\" })","t":"Inline code","g":"Code","x":"Call site:build(\"out\") to write every page. Every <code> tag is a Code , highlighted as Luwu unless you name another language."},{"p":"guide/code.html#languages","k":"section","t":"Languages","g":"Code","x":"The language is the second argument: CodeBlock(\"cargo build\", \"bash\") . Other languages are highlighted in the browser by highlight.js, and a page only loads it when it has code that needs it. \"plaintext\" isn't highlighted at all, and plain() turns the colors off for a single block."},{"p":"guide/code.html#squiggles","k":"section","c":"local name = \"Ada\" print(nmae) const typo = CodeBlock(\"local name = \\\"Ada\\\"\\nprint(nmae)\") :line_numbers() :squiggle( Squiggle.error(SourceSpan.on_line(2, 7, 10), \"Unknown global 'nmae'\"), Squiggle.info(SourceSpan.on_line(1, 7, 10), \"'name' is only used once\") )","t":"Squiggles","g":"Code","x":"A Squiggle underlines a span of code the way an editor marks an error and shows its message when the reader points at it: Squiggle.error , Squiggle.warning and Squiggle.info use the theme's editor colors. For any other color, use Squiggle(spans, color, message) . Each span is a SourceSpan : a start and an end, both a line and a column. SourceSpan.on_line(2, 7, 10) covers columns 7 to 10 of line 2, and SourceSpan.from_string(\"2.7-2.10\") reads the spans that luwu-analyze --formatter=gnu prints."},{"p":"guide/code.html#hovers","k":"section","c":"const cat = Cat(\"Nyla\") cat:feed(2) const hovered = CodeBlock(\"const cat = Cat(\\\"Nyla\\\")\\ncat:feed(2)\") :hover( Hover(SourceSpan.on_line(1, 7, 9), CodeBlock(\"const cat: Cat\")), Hover(SourceSpan.on_line(2, 5, 8), { CodeBlock(\"function Cat:feed(amount: number): Cat\"), Paragraph(\"Feeds the cat, so it's less hungry.\"), }) ) const nyla = Code(\"nyla\"):hover(Hover( SourceSpan.on_line(1, 1, 4), Card(\"Nyla\", Paragraph(\"A small, opinionated cat.\")) )) const fancy = Paragraph({ \"Hover \", nyla, \" to meet her.\" })","t":"Hovers","g":"Code","x":"A Hover shows content when the reader points at part of the code. A dotted underline tells them what to try. On a phone, tap it: A hover can hold anything, from plain text to code or your own components, and one over a squiggle shows both. The Better Hovers page uses them to show real hovers from Luwu's language server. Hover nyla to meet her."},{"p":"guide/code.html#your-own-code-elements","k":"section","c":"class FileSnippet implements SourceCode function tag(): string return \"figure\" end function __init(self, file: string?, source: string?, language: Language?) self.source = source or \"\" self :attr(\"data-file\", file) :attr(\"data-language\", language or \"luwu\") end function render(self, out: Writer) self:render_open(out) out:write(`<figcaption>{Text.escape(tostring(self:get_attr(\"data-file\")))}</figcaption>`) out:write(`<pre><code class=\"language-{self:language()}\">`) self:render_source(out) out:write(\"</code></pre></figure>\") end end Component.register(FileSnippet)","t":"Your own code elements","g":"Code","x":"To show code your own way, with a file name above it for example, implement SourceCode . Your class gets highlighting, squiggles and hovers too. Call render_source(out) where the code goes:"},{"p":"guide/styling.html","k":"page","t":"Styling","g":"Styling","x":"CSS has hundreds of properties, and a browser silently ignores a typo in any of them. In chimera a style is a Luwu table whose values Luwu's type function validators check during analysis: padding = \"1rx\" is a type error, and dispaly = \"flex\" gets a \"did you mean\". Styles can also read theme tokens, and then they follow the reader's theme with no extra CSS."},{"p":"guide/styling.html#one-element","k":"section","c":"const note = Paragraph(\"Back up your saves before updating.\") :style({ padding = \"0.75rem 1rem\", background = token(\"surface\"), border_left = `4px solid {token(\"accent\")}`, border_radius = token(\"radius\"), })","t":"One element","g":"Styling","x":"style sets an element's inline style: Back up your saves before updating. Keys are CSS property names with underscores instead of dashes. Keyword properties like display only accept their real values, while lengths also take plain numbers like margin = 0 . Vendor prefixes start with webkit_ or moz_ , and custom properties go in brackets: [\"--gap\"] = \"1rem\" ."},{"p":"guide/styling.html#theme-tokens","k":"section","c":"background surface text muted border primary primary_text accent radius spacing font mono_font shadow syntax_keyword syntax_string syntax_comment ... syntax_error","t":"Theme tokens","g":"Styling","x":"token(\"accent\") stands for var(--chimera-accent) , the current theme's accent color. When the reader switches themes, every style that uses it changes with them. These are the tokens every theme sets: token(\"radius\"):times(1.5) scales a length token, and token(\"primary\"):mix(token(\"background\"), 20) blends 20% of one color token into another."},{"p":"guide/styling.html#colors","k":"section","c":"const swatch = Paragraph(\"Tinted\") :style({ padding = \"0.5rem 1rem\", color = Color.named(\"white\"), background = Color.hex(\"#3b5bdb\"):mix(Color.named(\"black\"), 0.25), border_radius = token(\"radius\"):times(2), })","t":"Colors","g":"Styling","x":"Tinted Color.hex checks its literal while you type, and Color.named takes any CSS color name. Colors also convert to and from vectors, packed numbers, buffers and ANSI codes."},{"p":"guide/styling.html#inside-one-element","k":"section","c":"const credits = Footer({ Small(\"Art by Nyla.\"), Link(\"More art\", \"#\") }) :row() :style_inside(Link, { color = token(\"muted\") })","t":"Inside one element","g":"Styling","x":"style_inside styles the matching elements inside one element and leaves the rest of the page alone: Art by Nyla. More art"},{"p":"guide/styling.html#every-element-of-a-kind","k":"section","c":"site :style_every(Button, { border_radius = \"999px\" }) :style_every(Card, { padding = \"2rem\" }) :style_every(\".hero h1\", { font_size = \"3rem\" })","t":"Every element of a kind","g":"Styling","x":"style_every on a Document or a Site styles everything that matches an element class or a CSS selector. These rules come after the theme's and win over them:"},{"p":"guide/styling.html#rules-and-stylesheets","k":"section","c":"document:css({ Rule(\"nav a\", { color = token(\"text\") }), Rule(\"@media (max-width: 600px)\", {}, { Rule(\"nav\", { flex_direction = \"column\" }), }), })","t":"Rules and stylesheets","g":"Styling","x":"A Rule pairs a selector with a style. For media queries, nest rules inside one: document:css(text) also takes plain CSS, and link_stylesheet(href) links a stylesheet file. Going the other way, Rule.parse and Style.parse read CSS back into objects. Styles that a component always needs belong in the component itself, as Custom components shows."},{"p":"guide/theming.html","k":"page","t":"Theming","g":"Theming","x":"A reader whose OS is in dark mode should get a dark page, and one who picks Catppuccin Latte should keep getting Latte on every page after that. chimera handles both with themes. A theme is a class that sets the colors, fonts and spacing every element reads."},{"p":"guide/theming.html#defaults","k":"section","c":"site :default_dark_theme(catppuccin.Mocha) :default_light_theme(catppuccin.Latte)","t":"Defaults","g":"Theming","x":"Each page has one default theme for light mode and one for dark mode. Until the reader picks a theme of their own, the page follows their OS setting: Without defaults, pages use Light and Dark . A lone Document has the same methods."},{"p":"guide/theming.html#offering-more-themes","k":"section","c":"site :offer_theme(catppuccin.Macchiato) :offer_theme(catppuccin.Frappe) :offer_theme(Light) :offer_theme(Dark) const picker = Row({ Paragraph(\"Try a theme:\"), ThemeSwitcher() }):align(\"center\")","t":"Offering more themes","g":"Theming","x":"offer_theme adds a theme readers can pick, and a ThemeSwitcher lists it next to the defaults. This site offers six: Try a theme: The browser saves the reader's pick, and links between pages carry it too. That way it sticks even on a site opened straight from disk."},{"p":"guide/theming.html#built-in-themes","k":"section","t":"Built-in themes","g":"Theming","x":"Light and Dark : plain, neutral themes and the fallback defaults. catppuccin.Latte , Frappe , Macchiato and Mocha : the four Catppuccin flavors. Code is colored the way Catppuccin's own editor themes color it."},{"p":"guide/theming.html#your-own-theme","k":"section","c":"class Sepia() implements Theme const name = \"sepia\" const mode = \"Light\" function palette(self): Palette return Palette { background = Color.hex(\"#f4ecd8\"), text = Color.hex(\"#5b4636\"), primary = Color.hex(\"#8b5e3c\"), radius = \"2px\", } end end Theme.register(Sepia) site:offer_theme(Sepia)","t":"Your own theme","g":"Theming","x":"A theme is a class that implements Theme with a name , a mode and a palette . Any token you leave out of the Palette keeps its Light value: Theme.register lets the parser find the theme by name, and label() sets the name the switcher shows. To restyle the built-in elements themselves, override base_styles() . Every built-in style reads its colors from tokens. Write yours the same way and they'll follow your theme as well (see Styling )."},{"p":"guide/custom-components.html","k":"page","t":"Custom components","g":"Custom components","x":"Say your docs need a callout box on 40 pages. Pasting its HTML and CSS 40 times works until the day you change it. In chimera you write the callout once as a class that gets the same methods, type checking and theming as the built-in components."},{"p":"guide/custom-components.html#a-component","k":"section","c":"class Callout implements Component, Container function tag(): string return \"aside\" end function __init(self, title: string?, content: Content?) self:add(Strong(title), content) end function default_styles(self): { Rule } const callout = self:style_selector() return { Rule(callout, { display = \"block\", padding = \"0.75rem 1rem\", border_left = `4px solid {token(\"primary\")}`, background = token(\"surface\"), border_radius = token(\"radius\"), }), Rule(`{callout} > p`, { margin = \"0.25rem 0 0\" }), } end end Component.register(Callout) const warning = Callout(\"Heads up\", Paragraph(\"Saves from version 1 don't load in version 2.\"))","t":"A component","g":"Custom components","x":"Implementing Component lets your class go anywhere content goes, and Container lets it hold children. tag names the HTML tag it renders as: Heads up Saves from version 1 don't load in version 2. default_styles returns the CSS the component needs, and every page that uses the component includes those rules once. style_selector() gives the selector for the class's elements. Rules built on it only ever match your component."},{"p":"guide/custom-components.html#registering-it","k":"section","t":"Registering it","g":"Custom components","x":"Component.register(Callout) records the class under its name. Its elements then render with data-element=\"Callout\" , and the parser uses that attribute to rebuild them as Callout s (see Parsing HTML )."},{"p":"guide/custom-components.html#arranging-children","k":"section","t":"Arranging children","g":"Custom components","x":"Implement Layout instead of Container and your component also gets row() , grid() , gap() and the rest of the methods Layout describes."},{"p":"guide/custom-components.html#scripts-and-stylesheets","k":"section","c":"function head_elements(self): { Metadata }? return { Script(nil, \"https://cdn.example.com/charts.js\"):defer() } end","t":"Scripts and stylesheets","g":"Custom components","x":"When a component needs a script or a stylesheet in the page's <head> , return it from head_elements . A page gets each one once, however many of the components it holds: For a small handler, on(\"click\", script) is enough. It writes the code into the element's onclick attribute."},{"p":"guide/custom-components.html#rendering-your-own-html","k":"section","c":"function render(self, out: Writer) self:render_open(out) out:write(`<span class=\"count\">{#self.children}</span>`) for _, child in self.children do child:render(out) end out:write(\"</aside>\") end","t":"Rendering your own HTML","g":"Custom components","x":"By default a component renders its tag, its attributes and its children. For anything else, override render and use render_open to write the opening tag: The Writer knows about the page being rendered, including its path, the site's pages and the themes on offer. out:href_to(path) turns a path from the site's root into a link that works from the current page."},{"p":"guide/custom-components.html#printing-in-the-terminal","k":"section","t":"Printing in the terminal","g":"Custom components","x":"print(warning) shows the element in the terminal as a tree rather than as HTML. Override outline to change the one-line summary each node gets."},{"p":"guide/parsing-html.html","k":"page","t":"Parsing HTML","g":"Parsing HTML","x":"Say you have 200 pages of hand-written HTML and want to move them to chimera. Parser reads HTML back into chimera objects, turning a <p> into a Paragraph and a rendered Menu back into a Menu . You change the objects, then render them again."},{"p":"guide/parsing-html.html#parsing","k":"section","c":"const nodes = Parser():parse([==[ <nav data-element=\"Menu\" class=\"chimera-menu\"><a href=\"/\">Home</a><a href=\"/blog\">Blog</a></nav> <p>Hi <strong>there</strong></p> <dialog open>Sure?</dialog> ]==]) for _, node in nodes do print(node) end Menu<nav>.chimera-menu ├─ Link<a> href │ └─ \"Home\" └─ Link<a> href └─ \"Blog\" Paragraph<p> ├─ \"Hi \" └─ Strong └─ \"there\" Tag<dialog> open └─ \"Sure?\"","t":"Parsing","g":"Parsing HTML","x":"parse returns the top-level nodes it found: Each node prints as a tree. This output comes from running the code above as the page built: Tags that have a class become that class, and the rest become a Tag that keeps its name. Components come back from their data-element attribute."},{"p":"guide/parsing-html.html#whole-pages","k":"section","c":"const page = Parser():parse_document(fs.readfile(\"out/index.html\")) page:style_every(Card, { padding = \"2rem\" }) fs.writefile(\"out/index.html\", page:to_html(true))","t":"Whole pages","g":"Parsing HTML","x":"To edit a whole page, parse_document reads it into a Document : The parser drops the stylesheet and script chimera generated because the document writes them again when it renders. Your own style_every rules come back as rules. Any page chimera rendered parses back into the objects it came from."},{"p":"guide/parsing-html.html#problems","k":"section","c":"const parser = Parser() parser:parse(\"<ul><p>Not a list item</p></ul>\") print(parser.warnings[1]) UnorderedList can't hold Paragraph<p>; dropped it (at byte 27)","t":"Problems","g":"Parsing HTML","x":"Bad HTML never stops the parser. It drops whatever doesn't fit and notes each drop in warnings :"},{"p":"guide/parsing-html.html#your-own-components","k":"section","t":"Your own components","g":"Parsing HTML","x":"Components you write parse back as themselves once you register them with Component.register . Their adopt method decides which parsed children they keep (see Custom components ). HTML that chimera didn't write, like another site's <div class=\"alert\"> , can come back as your components too when they're Shape s (see Markdown and JSON )."},{"p":"guide/markdown-and-json.html","k":"page","t":"Markdown and JSON","g":"Markdown and JSON","x":"Read and write chimera pages as Markdown and JSON"},{"p":"guide/markdown-and-json.html#reading-markdown","k":"section","c":"Heading<h1> └─ \"Install\" Paragraph<p> ├─ \"Run \" ├─ Code.chimera-code data-language ├─ \", then read the \" ├─ Link<a> href │ └─ \"guide\" └─ \".\" UnorderedList<ul> ├─ ListItem<li> │ ├─ \"Clone \" │ └─ Strong │ └─ \"chimera\" └─ ListItem<li> └─ \"Point an alias at it\" const nodes = Markdown():parse(CodeBlock.dedent([==[ # Install Run `seal setup`, then read the [guide](guide.md). - Clone **chimera** - Point an alias at it ]==])) const page = Markdown():parse_document(fs.readfile(\"install.md\")) fs.writefile(\"install.html\", page:to_html(true))","t":"Reading Markdown","g":"Markdown and JSON","x":"Markdown():parse returns one node per block. It reads headings, paragraphs, emphasis, links, images, lists, quotes, code, tables and HTML: Inline code is Luwu unless you set code_language . Fenced code takes the language after the fence, and copyable or line-numbers after that turn on those settings. Links to .md files point at the .html pages built from them, so the guide link above goes to guide.html . Problems that don't stop reading, like HTML the parser can't place, end up in the reader's warnings . parse_document reads a whole file into a Document . Its title comes from the front matter's title or else the first level 1 heading, and its description from description :"},{"p":"guide/markdown-and-json.html#a-folder-of-markdown","k":"section","c":"Site(\"My docs\") :search() :add_pages(Markdown():pages(\"docs\")) :build(\"site\")","t":"A folder of Markdown","g":"Markdown and JSON","x":"pages reads every Markdown file in a folder into site pages. index.md becomes index.html and a subfolder's files become pages under the page of the same name, so guide.md gets the pages in guide/ . Pages sort by their front matter's order , then by name:"},{"p":"guide/markdown-and-json.html#html-inside-markdown","k":"section","c":"<details> <summary> See the docs </summary Reads the file at `path` to string. ## Errors - if `path` is not valid utf-8 </details> Details ├─ Summary │ └─ \" See the docs \" ├─ Paragraph<p> │ ├─ \"Reads the file at \" │ ├─ Code.chimera-code data-language │ └─ \" to string.\" ├─ Heading<h2> │ └─ \"Errors\" └─ UnorderedList<ul> └─ ListItem<li> ├─ \"if \" ├─ Code.chimera-code data-language └─ \" is not valid utf-8\"","t":"HTML inside Markdown","g":"Markdown and JSON","x":"HTML in Markdown goes through the Parser , so components written as HTML come back as components. A tag alone on its line wraps the Markdown up to its closing tag. seal's docs put <details> around each function's documentation that way, and even leave a </summary unclosed: chimera reads it into a Details with its Summary, the way a browser would:"},{"p":"guide/markdown-and-json.html#writing-markdown","k":"section","c":"<div data-element=\"Card\" class=\"chimera-card\"> ### Fast Renders **thousands** of pages a second. - No server - No build step </div> const card = Card(\"Fast\", { Paragraph({ \"Renders \", Strong(\"thousands\"), \" of pages a second.\" }), UnorderedList({ \"No server\", \"No build step\" }), }) const markdown = card:to_markdown()","t":"Writing Markdown","g":"Markdown and JSON","x":"Every node has to_markdown . Parts Markdown has no syntax for, like a component or an element with a style class, keep their HTML. A container of blocks writes its tags on lines of their own with Markdown between them, so the text stays readable and reads back as the same component: Your own elements write Markdown in a markdown method. It gets a MarkdownWriter for its children: out:inline(...) for text inside a line and out:blocks(...) for blocks. The callout below writes itself as a quote."},{"p":"guide/markdown-and-json.html#json","k":"section","c":"{ \"children\": [ { \"text\": \"Hi \" }, { \"children\": [ { \"text\": \"there\" } ], \"tag\": \"strong\" } ], \"tag\": \"p\" } const text = Json.encode(Paragraph({ \"Hi \", Strong(\"there\") }), true) const again = Json.decode(text)","t":"JSON","g":"Markdown and JSON","x":"Json.encode writes any node as the tree its HTML has, and Json.decode reads it back into the same nodes, components included. Json.tree gives the tree as tables for tools written in Luwu: Each element has its tag , its component in element and its attributes in the order it renders them. Encoding a page and decoding it gives the same HTML: true ."},{"p":"guide/markdown-and-json.html#recognizing-your-components","k":"section","c":"Callout<aside>.callout └─ Paragraph<p> └─ \"Back up first.\" Callout<aside>.callout └─ Paragraph<p> └─ \"Careful.\" class Callout implements Shape, Container function tag(): string return \"aside\" end function __init(self, content: Content?) self :add_style_class(\"callout\") :add(content) end -- A quote that starts with **Note:**, or another site's <div class=\"alert\">. function recognize(node: Element): Shape? if class.isinstance(node, BlockQuote) when const first = node.children[1] when class.isinstance(first, Paragraph) when const lead = first.children[1] when class.isinstance(lead, Strong) when text_of(lead) == \"Note:\" then table.remove(first.children, 1) if const rest = first.children[1] when class.isinstance(rest, Text) then rest.content = string.gsub(rest.content, \"^%s+\", \"\") end return Callout(node.children) elseif class.isinstance(node, Div) and node:has_style_class(\"alert\") then return Callout(node.children) end return nil end function markdown(self, out: MarkdownWriter): string const text = `**Note:** {out:blocks(self.children)}` return \"> \" .. string.gsub(text, \"\\n\", \"\\n> \") end end Component.register(Callout) Shape.register_shape(Callout) const from_markdown =","t":"Recognizing your components","g":"Markdown and JSON","x":"Markdown from someone else won't say which of your components it means. A quote that starts with **Note:** is a callout to you and a plain quote to the Markdown reader. A Shape is a component that recognizes itself in what the readers read. Its recognize gets each parsed element, children first, and returns the component that element stands for. Markdown, HTML and JSON all try every registered shape: Both came back as callouts. Its markdown method writes the quote again, so a callout survives a trip through Markdown: > **Note:** Back up first. . Fenced code blocks can become components too. fence takes a language and a function that builds the content for each block in it: For whole pages of HTML, see Parsing HTML ."},{"p":"luwu/index.html","k":"page","t":"Luwu","g":"Luwu","x":"Luwu is a fast, object oriented, and highly expressive embeddable scripting language forked from Luau 0.730 and influenced by Kotlin, Rust, Ruby, and Python. Luwu is designed around improving the developer experience, with a user-first type system focused on surfacing useful hovers and error reporting in modern, industry standard editors, new features that make everyday code easier to read and write, and incremental improvements that improve analysis in both existing Luau as well as greenfield Luwu projects."},{"p":"luwu/index.html#what-luwu-is-for","k":"section","t":"What Luwu is for","g":"Luwu","x":"Luwu is built for code that models behavior and data, such as: gameplay scripting data modeling data transformation tools and scripts that grow into real programs"},{"p":"luwu/index.html#your-first-program","k":"section","c":"type Item = { name: string, price: number, stock: number } const inventory: { Item } = { { name = \"apple\", price = 1.25, stock = 12 }, { name = \"pear\", price = 0.8, stock = 0 }, { name = \"kiwi\", price = 0.5, stock = 30 }, } const in_stock = { for _, item in inventory when item.stock > 0 give item } table.sort(in_stock, function(a: Item, b: Item) return a.price < b.price end) for _, .{ name, price } in in_stock do print(`{name}: {price}`) end seal ./fruit.luwu kiwi: 0.5 apple: 1.25","t":"Your first program","g":"Luwu","x":"Luwu files end in .luwu . If you've written Luau, this short program should look familiar. It keeps a small inventory, picks out the fruit that's in stock and prints it cheapest first: Most of it is the Luau you already know. The { for ... when ... give item } line is a table comprehension: it builds the filtered array in a single expression. In the second loop, for _, .{ name, price } uses destructuring to pull just the fields you need out of each item. You don't need two more lines of code just to put item.name and item.price into local variables. Run fruit.luwu with seal , a Luau and Luwu runtime:"},{"p":"luwu/index.html#luwu-and-luau","k":"section","t":"Luwu and Luau","g":"Luwu","x":"Luwu was forked by the Nyla, Hina & Ferris Discord community to better suit our needs for general-purpose programming outside of Roblox. In addition to popular Luau features such as string interpolation, generalized iteration, compound assignment operators, the new type solver (with type functions!), const syntax, if local , and more, Luwu code also features highly optimized classes and objects with code reuse facilitated via traits, table/object/userdata destructuring, do expressions, table comprehensions, the none primitive, externally managed buffers, and more. Since the fork, Luau and Luwu have diverged. The main differences today are in classes and inheritance, integers, and destructuring. See Compatibility → The sections below give a short tour of each feature."},{"p":"luwu/index.html#types-and-editor-support","k":"section","t":"Types and editor support","g":"Luwu","x":"We maintain our LSP and the Luwu VSCode/Code-OSS extension alongside the language. New editor features and type checking improvements are developed directly against them, and we see how every change reads in a real editor before it ships. That's also why Luwu prints types and errors differently from Luau. Luau is primarily developed against Roblox's Studio script editor and stringifies types to fit the single-line diagnostics Studio shows. Our language server targets VSCode/Code-OSS (with hopefully more editors coming soon!) where hovers and diagnostics span several lines. Luwu prints types over multiple lines formatted like code and writes its error messages for people reading them in a hover. We've also added context to Luwu's type errors that makes them easier for tools to work with."},{"p":"luwu/index.html#type-checking","k":"section","t":"Type Checking","g":"Luwu","x":"Luwu enables type checking by default to catch your code's mistakes before you run it. Luwu builds upon Luau's new type solver to add new features, drastically improve error message friendliness and readability, and catch more common mistakes. Luwu type checking defaults to a relatively strict mode, but you can go back to the autocomplete-only Luau default with --!nonstrict (or all the way to --!nocheck for untyped Lua code). Note that due to popular demand, we surface typos even in --!nonstrict . See Type Checking →"},{"p":"luwu/index.html#literal-types-and-validators","k":"section","t":"Literal Types and Validators","g":"Luwu","x":"A literal type requires a value written directly at the call, such as \"#3b5bdb\" or \"1.5rem\" , and a validator is a type function that checks that literal during analysis. Your own APIs can use them to reject a malformed color, size or route in the editor with an error message you write yourself. See Literal Types and Validators →"},{"p":"luwu/index.html#lints","k":"section","t":"Lints","g":"Luwu","x":"We also expand Luau's built-in lint system with more than 40 new lints for Luau and Luwu code, to help you write more idiomatic and performant code. See Lints →"},{"p":"luwu/index.html#better-hovers","k":"section","t":"Better Hovers","g":"Luwu","x":"Our hovers target luwu-lsp and the Luwu VSCode/Code-OSS extension and significantly improve recursive type stringification. A hover exposes every relevant type with verbosity levels and go to location links you can click. Overloads and unions are serialized in a more readable way, and each type with documentation attached shows one line of it above. See Better Hovers →"},{"p":"luwu/index.html#objects-and-data","k":"section","t":"Objects and data","g":"Luwu"},{"p":"luwu/index.html#classes-and-traits","k":"section","c":"class Health private ( private current: number, public const max_health: number ) public function full(max_health: number): Health return Health(max_health, max_health) end private function clamped(current: number, max_health: number): Health if math.isnan(current) then error(\"health can't be NaN\", 3) end return Health(math.clamp(current, 0, max_health), max_health) end public function __add(self, amount: number): Health return Health.clamped(self.current + amount, self.max_health) end public function __sub(self, amount: number): Health return Health.clamped(self.current - amount, self.max_health) end -- ... comparisons (__eq, __lt, __le) and a healthbar __tostring end local hp = Health.full(100) print(hp) hp -= 65 print(hp) hp += 500 print(hp, hp == Health.full(100)) hp -= 90 print(hp, hp < Health.full(20)) seal ./health.luwu","t":"Classes and Traits","g":"Luwu","x":"A class represents a domain specific concept for your program, such as Player and Health classes in a game. In Luwu, you can use classes to abstract related functionality into components that make sense and use traits to share functionality that multiple classes need to use. Classes are also great for representing data that needs to rely upon certain properties always valid, such as health being clamped between 0 and max_health , age not being negative, positions not being NaN, etc. This Health example represents the concept of health points and protects the fact that health must always be valid, and has a nice healthbar display for when you print it out to a terminal: The healthbar's colors come from seal's @std/io/colors library. Save the full example as health.luwu and run it with seal : ████████████████████ 100/100 ███████ ░░░░░░░░░░░░░ 35/100 ████████████████████ 100/100, true ██ ░░░░░░░░░░░░░░░░░░ 10/100, true See the full example on the Classes and Traits page →"},{"p":"luwu/index.html#destructuring","k":"section","c":"const player = { name = \"Ada\", level = 12 } const .{ name, level } = player print(name, level) const tasks = { { title = \"Feed Nyla\", done = true }, { title = \"Write docs\", done = false }, } for _, .{ title, done } in tasks do print(title, done) end","t":"Destructuring","g":"Luwu","x":"Destructuring pulls several fields into locals at once from anything you can index with a dot: tables, objects, classes and userdata. It's similar to destructuring assignment in JavaScript and destructuring patterns in Rust. Use it in local and const declarations: And in a for loop's header: See Destructuring →"},{"p":"luwu/index.html#restructuring","k":"section","c":"const name, age = \"Ada\", 36 const person = .{ name, age } print(person.name, person.age)","t":"Restructuring","g":"Luwu","x":"The same syntax on the right of = builds a table instead: .{ name, age } is equivalent to { name = name, age = age } . It's similar to shorthand properties in JavaScript and field init shorthand in Rust. Class.{ name, age } builds a class without a primary constructor the same way."},{"p":"luwu/index.html#the-none-primitive","k":"section","c":"const list = { \"first\", none, \"third\" } print(#list)","t":"The none Primitive","g":"Luwu","x":"none means \"intentionally empty\". Unlike nil, you can store it in a table. See The none Primitive →"},{"p":"luwu/index.html#everyday-code","k":"section","t":"Everyday code","g":"Luwu"},{"p":"luwu/index.html#expressive-control-flow","k":"section","c":"const users: { [string]: { name: string, admin: boolean }? } = { ada = { name = \"Ada\", admin = true }, grace = { name = \"Grace\", admin = false }, } if const user = users[\"ada\"] when user.admin then print(`{user.name} is an admin`) end const prices: { [string]: number? } = { apple = 1.25, pear = 0.8 } for _, fruit in { \"apple\", \"kiwi\", \"pear\" } when const price = prices[fruit] do print(`{fruit} costs {price}`) end const scores = { 72, 95, 88 } const best = do local top = 0 for _, score in scores do top = math.max(top, score) end give top print(best) const function describe(fruit: string): string const price = prices[fruit] or return `{fruit} isn't sold here` return `{fruit} costs {price}` end","t":"Expressive Control Flow","g":"Luwu","x":"Expressive control flow is a set of features that let you get a value, check it and decide what to do with it in one expression. Combined, they make Luwu a more expression-focused language than Python or Luau and make data transformation code much easier to read. if local and if const bind a value inside the condition and when adds more checks that can use it: Loops take when chains too and skip the items that fail them: A do expression runs statements anywhere an expression goes and give s back a value. In Luwu we prefer do / give blocks over temporary and intermediate variables. They're useful in a lot of places: Making obvious what the code is actually building up by scoping the computation inside the expression that produces the value. Putting several statements where only an expression fits, like a table field or an argument. Debugging a value in place: do print(x) give x . Costing nothing: unlike a function call that abstracts the same computation, they're always inlined. or return , or continue and or break leave as soon as a value is missing: See Expressive Control Flow →"},{"p":"luwu/index.html#table-comprehensions","k":"section","c":"const numbers = { 1, 2, 3, 4, 5, 6 } const even_squares = { for _, n in numbers when n % 2 == 0 give n * n } print(#even_squares)","t":"Table Comprehensions","g":"Luwu","x":"A table comprehension builds a new table from a loop, in one expression. See Table Comprehensions →"},{"p":"luwu/index.html#default-arguments","k":"section","c":"const function greet(name: string, greeting = \"Hello\") print(`{greeting}, {name}!`) end greet(\"Ada\")","t":"Default Arguments","g":"Luwu","x":"Function parameters and class constructor parameters can have default values: See Default Arguments →"},{"p":"luwu/index.html#named-functions-in-table-literals","k":"section","c":"local handlers = { on_start = function() print(\"started\") end, } handlers.on_start() const handlers = { function on_start() print(\"started\") end, function on_stop() print(\"stopped\") end, } handlers.on_start() handlers.on_stop()","t":"Named functions in table literals","g":"Luwu","x":"In Luau, a function stored in a table is a key assigned an anonymous function: In Luwu, you can declare it like any other function, with function name() inside the table: It reads the same as a const function or a class method, and a function without a name is still a list item, like in Luau."},{"p":"luwu/index.html#importing-classes-with-their-types","k":"section","c":"local shapes = require(\"./shapes\") local Circle = shapes.Circle type Circle = shapes.Circle export class Circle(radius: number) function area(self): number return math.pi * self.radius ^ 2 end end const shapes = require(\"./shapes\") const Circle = shapes.Circle const .{ Circle } = require(\"./shapes\") const function describe(circle: Circle): string return `a circle with area {circle:area()}` end","t":"Importing classes with their types","g":"Luwu","x":"In Luau, a value and a type are imported separately. A class-like table needs both lines: A Luwu class is a value and a type at once. Given a module that exports one: Importing the class brings its type along, whichever way you import it: Traits work the same way. type Circle = shapes.Circle still works, but isn't needed."},{"p":"luwu/index.html#libraries-and-embedding","k":"section","t":"Libraries and embedding","g":"Luwu"},{"p":"luwu/index.html#library-extensions","k":"section","c":"const party = { \"Ada\", \"Grace\", \"Alan\" } table.drop(party, \"Grace\") print(#party)","t":"Library Extensions","g":"Luwu","x":"Luwu adds a few library functions. table.drop removes items from a list by value. Unlike table.remove(t, table.find(t, x)) , it doesn't remove the last item when x is missing. More are planned, like table.keys , table.extend and string.startswith . See Library Extensions →"},{"p":"luwu/index.html#external-buffers-and-strings","k":"section","t":"External Buffers and Strings","g":"Luwu","x":"Embedders can expose huge files to scripts without cloning them into the VM. See External Buffers and Strings →"},{"p":"luwu/index.html#experimental-features","k":"section","t":"Experimental Features","g":"Luwu","x":"Push and pop operators, and match expressions. They work today, but their design may still change. See Experimental Features →"},{"p":"luwu/compatibility.html","k":"page","t":"Compatibility","g":"Compatibility","x":"A Luau library written for Luau 0.730 or earlier runs in Luwu without changes. The reverse doesn't hold: once a file uses classes or table comprehensions it's Luwu code, and upstream Luau can't run it. Luwu keeps the two apart by file extension, and it refuses Luwu syntax in a .luau file so that file stays valid Luau."},{"p":"luwu/compatibility.html#luau-code-in-luwu","k":"section","t":"Luau code in Luwu","g":"Compatibility","x":"Luwu accepts valid Luau code up to and including Luau 0.730, and with it every RFC upstream accepted by 2026-07-17. RFCs accepted upstream after 0.730 aren't covered by that guarantee. UPSTREAM.md in the Luwu repository lists which upstream RFCs Luwu implements, which it replaced and which it skipped."},{"p":"luwu/compatibility.html#where-luau-and-luwu-diverge","k":"section","t":"Where Luau and Luwu diverge","g":"Compatibility","x":"Since the fork, Luau and Luwu have diverged. The main differences today are in classes and inheritance, integers, and destructuring: Classes and inheritance. Upstream's classes RFC adds implementation inheritance through open class and extends . Its private members have to start with _ and are read through new ._ and :_ operators that only exist inside methods. Luwu's classes have no inheritance and share code through traits instead. Private members keep ordinary names, and every method call checks that self really is an object of its class. Integers. Upstream's 64-bit integer type is a single signed integer with no arithmetic operators: adding two of them takes integer.add(a, b) . It was never enabled on Roblox and isn't covered by Luau's compatibility promise. Luwu is building its own, with separate signed and unsigned types, arithmetic operators and bigints. Destructuring. Upstream accepted key destructuring in 2024 and withdrew it a month later. Its current proposal mirrors table constructors, so every name is written twice: local {name = name, kind = kind} = entry . In Luwu you write each name once with const .{ name, kind } = entry , and it works on tables, objects and userda"},{"p":"luwu/compatibility.html#file-extensions","k":"section","t":"File extensions","g":"Compatibility","x":"Every module has a language, and Luwu takes it from the file's extension. The command-line tools and the language server agree on it: Extension Language .luwu Luwu .luau Luau .lua Lua A project can mix them freely. A .luwu module can require a .luau one, and the other way around."},{"p":"luwu/compatibility.html#luwu-syntax-in-luau-files","k":"section","c":"local fruit = { \"apple\", \"kiwi\", \"pear\" } local long_names = { for _, name in fruit when #name > 4 give name } table.drop(fruit, \"kiwi\") print(#long_names, #fruit)","t":"Luwu syntax in Luau files","g":"Compatibility","x":"Luwu could accept its own syntax everywhere, but then a .luau file could quietly stop being Luau. It would still run in Luwu and break the day someone opens it in upstream tooling, or in Roblox. So Luwu refuses: in a .luau module, Luwu-only syntax is a parse error that says what to do instead. Both messages come straight from luwu-analyze with the file saved as inventory.luau . Rename it to inventory.luwu and the same code checks cleanly. The parser can't reject library functions because they aren't syntax. Instead the LuwuOnlyApi lint warns about Luwu-only functions like table.drop and class.of in Luau and Lua files. The language server does the same for Luwu-only directives such as --!trust ."},{"p":"luwu/compatibility.html#luwuonly","k":"section","t":"luwuOnly","g":"Compatibility","x":"Behind those errors, the parser marks every syntax node that only Luwu accepts with a luwuOnly flag. It goes on the smallest node whose own syntax is Luwu's, so a default argument marks its function but leaves the function's body alone. Children of a marked node aren't marked unless their own syntax is Luwu-only as well. Tools can read the flag through Luwu's AST reflection ( node:luwuOnly() ). That's how a transpiler from Luwu to Luau finds exactly the nodes it has to rewrite and leaves everything else as it was."},{"p":"luwu/type-checking.html","k":"page","t":"Type Checking","g":"Type Checking","x":"By default, Luwu type checks your code in strict mode and reports mistakes in your editor as you write them. A file that needs to can opt out of strict checking. Values are still dynamically typed at runtime, and typing is gradual: you can start from untyped code, add type annotations a piece at a time and let inference handle most of the rest."},{"p":"luwu/type-checking.html#catching-mistakes","k":"section","c":"type Player = { name: string, level: number } const function promote(player: Player) player.level += 1 end promote({ name = \"Ada\", levl = 3 }) Typo: Did you mean 'level' instead of 'levl'? TypeError: The given table is missing a property for 'Player': • 'level: number'","t":"Catching mistakes","g":"Type Checking","x":"A typo in a field name is a type error, reported where you made it: Without the checker, this program would fail later, when something reads the missing level."},{"p":"luwu/type-checking.html#inference","k":"section","c":"const function average(numbers: { number }) local total = 0 for _, n in numbers do total += n end return total / #numbers end const result = average({ 4, 8, 15 }) print(result)","t":"Inference","g":"Type Checking","x":"Most code needs few annotations. Luwu infers the types of locals, return values and tables for you: Here only the parameter is annotated. total and the return value are inferred as numbers, and result is a number too."},{"p":"luwu/type-checking.html#gradual-typing","k":"section","c":"const function label(name, count) return `{name} x{count}` end print(label(\"Potion\", 3)) const function label(name: string, count: number): string return `{name} x{count}` end print(label(\"Potion\", 3))","t":"Gradual typing","g":"Type Checking","x":"Untyped code still runs and still type checks. Its parameters accept anything until you annotate them: Adding annotations later tightens the checks without changing how the code runs: To opt a file out of strict checking, put --!nonstrict or --!nocheck on its first line."},{"p":"luwu/type-checking.html#annotations-and-the-compiler","k":"section","t":"Annotations and the compiler","g":"Type Checking","x":"Type annotations also inform the compiler. Upstream Luau already uses them as optimization hints. Luwu goes further: in a file marked --!trust , the compiler relies on annotations to inline methods, and an annotation that doesn't match the actual value becomes a runtime error."},{"p":"luwu/type-checking.html#error-messages","k":"section","t":"Error messages","g":"Type Checking","x":"Luau's type errors describe where the checker's subtyping test failed. Luwu's describe the mistake in terms of your code: the variable's name, the path to the bad property, and how to fix it when there's a common fix. We purposely limit jargon in type errors. Terms like subtyping, variance or invariance stay out of a message unless it can't be understood without them. And when one is needed, we like to attach a \"Help\" explanation to describe what the term is and why we've flagged your code because of it. Nyla finding a recursive CYCLE in her fancatstic library. Art by Cat! (@meowzer_meow on Discord) Luwu names things the way your code does. Where Luau says \"this\" or expands a whole expanded type, Luwu uses the variable's name or the path to the property (like stool.inputs[i].count ), or the type's alias. Where possible, Luwu will try to add blue 'Info' notes (spans) to error messages to help you track down the root cause of a property mismatch, following it through multiple variables if needed. This means you don't have to manually trace error string paths back to where they came from. The examples below were checked with upstream Luau 0.742's luau-analyze and with luwu-analyze . T"},{"p":"luwu/type-checking.html#typos","k":"section","c":"--!strict local player_name = \"Ada\" print(player_nmae) main.luau(3,7): TypeError: Typo 'player_nmae': Did you mean 'player_name'? --!strict local player_name = \"Ada\" print(player_nmae) main.luau(3,7): TypeError: Unknown global 'player_nmae'; consider assigning to it first --!strict pirnt(\"hello\") main.luau(2,1): TypeError: Typo 'pirnt': Did you mean 'print'? --!strict pirnt(\"hello\") main.luau(2,1): TypeError: Unknown global 'pirnt'; consider assigning to it first --!strict type Player = { name: string, level: number } local ada: Player = { name = \"Ada\", levl = 3 } main.luau(4,37): Typo: Did you mean 'level' instead of 'levl'? main.luau(4,21): TypeError: 'ada' is missing a property for 'Player': • 'level: number' --!strict type Player = { name: string, level: number } local ada: Player = { name = \"Ada\", levl = 3 } main.luau(4,21): TypeError: Table type '{ levl: number, name: string }' not compatible with type 'Player' because the former is missing field 'level' --!strict type Options = { title: string, subtitle: string?, width: number? } local function open_window(options: Options) end open_window({ title = \"Inventory\", subtilte = \"Items\" }) main.luau(6,36): Typo: Did you mean 'su","t":"Typos","g":"Type Checking","x":"Luwu looks for typos wherever a name or a string is checked against a known set: locals, globals, properties, methods, library functions, type names, string literals and tagged union tags. Luau reports most of these as something else, like a missing property, or not at all. Misspelled locals A misspelled local: Misspelled globals Built-in globals count too. Luau suggests assigning to the misspelled name: Misspelled properties Luau reports the property the table is missing. Luwu also says which key was meant to be it: Misspelled optional properties When the property you meant is optional, nothing is missing. Luau 0.742 reports nothing at all, and the subtitle is silently lost. Luwu still catches it: Misspelled property reads Luau says the key isn't in the table. Luwu says which property you meant, by its path: Misspelled property writes Luau says the property can't be added to the table. Luwu says which existing property you meant: Misspelled methods Methods on built-in types, like strings, count too: Misspelled library functions Luau shows the library's internal type, typeof(table) . Luwu suggests the function you meant: Misspelled type names Type names count too: String literal ty"},{"p":"luwu/type-checking.html#unknown-names","k":"section","c":"--!strict local function load_save() local save_data = { level = 3 } return true end load_save() print(save_data.level) main.luau(8,7): TypeError: Unknown variable 'save_data', define it with 'local save_data = value' --!strict local function load_save() local save_data = { level = 3 } return true end load_save() print(save_data.level) main.luau(8,7): TypeError: Unknown global 'save_data'; consider assigning to it first --!strict print(greeting) local greeting = \"hello\" main.luau(2,7): TypeError: Can't use 'greeting' defined on line 3 before it exists --!strict print(greeting) local greeting = \"hello\" main.luau(2,7): TypeError: Unknown global 'greeting'; consider assigning to it first --!strict local function open_chest(locked: boolean): number if not locked then local reward = 10 end return reward end main.luau(6,12): TypeError: 'reward' is not accessible here because it was defined in an inner scope on line 4 main.luau(4,15): Note: Consider moving this binding above this 'if' statement to use it on line 6 --!strict local function open_chest(locked: boolean): number if not locked then local reward = 10 end return reward end main.luau(6,12): TypeError: Unknown global 'reward'; cons","t":"Unknown names","g":"Type Checking","x":"Luau reports every name it can't find as an unknown global, and suggests assigning to it. Luwu suggests defining a local instead because code rarely means to create a global. When there's a better explanation, Luwu gives that: a local used too early, one out of scope, or a module that was never required. Undefined variables A name used outside the function that defines it: Use before definition A local used above its own definition: Inner scopes A local defined inside an if, then used after it: Missing library functions Luau shows the library's internal type, typeof(string) . Luwu names the library: Unknown qualified types Luwu says which half of math_utils.Point is wrong:"},{"p":"luwu/type-checking.html#tables","k":"section","c":"--!strict type Stack = { id: string, count: number } type Recipe = { output: Stack, inputs: { Stack }, station: \"bench\" | \"forge\" | \"loom\", } local recipes: { [string]: Recipe } = {} local stool = { output = { id = \"stool\", count = 1 }, inputs = { { id = \"plank\", count = \"3\" } }, station = \"workbench\" :: string, } recipes.stool = stool main.luau(16,17): TypeError: Expected 'stool' to be 'Recipe?' but was given '{ inputs: {{ count: string, … }}, station: string, … }' Some properties are incompatible: • stool.inputs[i].count: expected 'number', got 'string' • stool.station: expected '\"bench\" | \"forge\" | \"loom\"', got 'string' main.luau(2,28): Note: Expected 'count: number' because of this main.luau(13,32): Note: 'count' is 'string' here, but should be 'number' main.luau(6,5): Note: Expected 'station: \"bench\" | \"forge\" | \"loom\"' because of this main.luau(14,5): Note: 'station' is 'string' here, but should be '\"bench\" | \"forge\" | \"loom\"' Help (paths above): • '[i]' is any element of an array --!strict type Stack = { id: string, count: number } type Recipe = { output: Stack, inputs: { Stack }, station: \"bench\" | \"forge\" | \"loom\", } local recipes: { [string]: Recipe } = {} local","t":"Tables","g":"Type Checking","x":"Luwu names the variable, writes the path to each bad property the way you'd index it, and lists every problem at once. Tables with several mistakes Luau names the two types without saying why they don't match. Luwu lists every property that doesn't fit by its path: Nested maps and arrays Luau describes the path through each indexer step by step. Luwu writes it the way you'd index it: Missing properties A color nested two levels deep in a theme is missing its blue channel. Luau describes the table by its expanded type. Luwu names it by the path from the variable, dark.colors.text : Missing properties through other variables The color is built in white , stored in colors , then passed in a call. Luau names white but not what's wrong with it. Luwu follows the value back and names the missing property by its path, colors.background.b : Records where a map is expected Luau names the two types. Luwu says what kind of mismatch it is: Unrelated tables Luau names the two aliases. Luwu spells out both shapes next to their names. Because they share no properties, Luwu says the types are unrelated instead of listing every difference: you most likely passed the wrong value. Recursive types A JS"},{"p":"luwu/type-checking.html#unions-and-tagged-unions","k":"section","c":"--!strict type Shape = | { kind: \"circle\", radius: number } | { kind: \"rect\", width: number, height: number } local function area(shape: Shape): number return 0 end area({ kind = \"rect\", width = 4, height = \"3\" }) main.luau(10,6): TypeError: Expected this to be type Shape = … | { height: number, kind: \"rect\", width: number } but was given '{ height: string, kind: \"rect\", … }' 'given.kind' is '\"rect\"', so 'given' was compared with Shape#2: • given.height: expected 'number', got 'string' main.luau(4,38): Note: Expected 'height: number' because of this --!strict type Shape = | { kind: \"circle\", radius: number } | { kind: \"rect\", width: number, height: number } local function area(shape: Shape): number return 0 end area({ kind = \"rect\", width = 4, height = \"3\" }) main.luau(10,6): TypeError: Expected this to be '{ height: number, kind: \"rect\", width: number } | { kind: \"circle\", radius: number }' but got '{ height: string, kind: \"rect\", width: number }' --!strict type Message = | { kind: \"text\", body: string } | { kind: \"image\", url: string, width: number, height: number } | { kind: \"poll\", question: string, options: { string } } local function send(message: Message) end send({}) ","t":"Unions and tagged unions","g":"Type Checking","x":"Luwu reads a tagged union's tag to find the variant you meant, then explains what doesn't fit that variant. Wrong property types in tagged unions A tagged union, like an enum with data, uses one property (here kind ) to say which variant a table is. Luau prints the whole union and the given table. Luwu reads the tag, compares the table with the matching variant and points at the wrong property: Empty tables for tagged unions Starting from an empty table, Luau prints the whole union. Luwu lists the tag every variant needs, then what each variant needs on top of it: Missing properties in a variant Luau finds the variant too, and prints both table types in full. Luwu names the exact item in the list, and the property it needs: Unions Luau lists the members that don't fit. Luwu shows the member closest to fitting, and what it's missing:"},{"p":"luwu/type-checking.html#functions","k":"section","c":"--!strict type Validate = (input: string) -> (boolean, string?) local validate: Validate = function(input: string): (string?, boolean) return nil, #input > 0 end main.luau(4,28): TypeError: Expected 'validate' to be '(input: string) -> (boolean, string?)' but was given '(input: string) -> (string?, boolean)' Help (return order): • The 1st and 2nd return values look like they're in the wrong order --!strict type Validate = (input: string) -> (boolean, string?) local validate: Validate = function(input: string): (string?, boolean) return nil, #input > 0 end main.luau(4,28): TypeError: Expected this to be '(string) -> (boolean, string?)' but got '(string) -> (string?, boolean)'; this is because * Expected the 1st return value to be `boolean`, but got `nil` * Expected the 1st return value to be `boolean`, but got `string` * Expected the 2nd return value to be `string?`, but got `boolean` --!strict type Stack = { id: string, count: number } type Filter = (slot: Stack?, index: number) -> boolean local is_plank: Filter = function(slot: Stack, index: number): boolean return slot.id == \"plank\" end main.luau(5,26): TypeError: Expected 'is_plank' to be '(slot: Stack?, index: number) -> bool","t":"Functions","g":"Type Checking","x":"Luwu prints function types with their parameter names, and explains each parameter and return value that doesn't fit. Swapped return values Luau reports three separate problems with the 1st and 2nd values. Luwu sees that they're swapped: Callbacks that accept too little Luau reports that a type isn't a supertype of nil. Luwu explains who passes the nil: An array instead of a single value Extra parameters Luau compares the parameter lists as a whole. Luwu names the extra parameter: Swapped parameters Luau reports both parameters separately. Luwu notices they're in the wrong order: Functions inside tables Luau describes its path through the plugin's hooks, and adds a second reason about type packs. Luwu names the function and the parameter that doesn't fit: Overloads Luau doesn't name the function, and prints every overload on one line. Luwu names the function, shows the arguments you passed, and lists each overload with its parameter names:"},{"p":"luwu/type-checking.html#metatable-classes","k":"section","c":"--!strict type EnemyImpl = { __index: EnemyImpl, new: (name: string, health: number) -> Enemy, take_damage: (self: Enemy, amount: number) -> boolean, } export type Enemy = typeof(setmetatable({} :: { name: string, health: number }, {} :: EnemyImpl)) type BossImpl = EnemyImpl & { phase: (self: Boss) -> number, } export type Boss = typeof(setmetatable({} :: { name: string, health: number, enraged: boolean }, {} :: BossImpl)) local Enemy = {} :: EnemyImpl local Boss = setmetatable({}, { __index = Enemy }) :: BossImpl Boss.take_damage = function(self: Boss, amount: number): number self.health -= amount return self.health end main.luau(17,20): TypeError: Expected 'Boss.take_damage' to be '(self: Enemy, amount: number) -> boolean' but was given '(self: Boss, amount: number) -> number' This function can be passed a value it doesn't accept: • missing property 'self.enraged: boolean' It should return: • 'boolean', not 'number' main.luau(12,78): Note: Expected 'enraged: boolean' because of this main.luau(7,47): Note: 'self' is missing 'enraged: boolean' --!strict type EnemyImpl = { __index: EnemyImpl, new: (name: string, health: number) -> Enemy, take_damage: (self: Enemy, amount: number","t":"Metatable classes","g":"Type Checking","x":"Metatables are how Luau code builds objects. Their types are large and refer back to themselves. Luwu prints them by name instead of expanding them. Metatable inheritance Classes built from metatables have recursive types. Luau prints them in full, with *CYCLE* markers where the type refers back to itself. Luwu prints the types by name, and lists the two problems with the overriding method: Generic metatable classes Promise.all can't give a list of strings here because one of the promises resolves to a number. Luau 0.742 accepts the code without an error. Luwu finds the generic parameter no type can satisfy:"},{"p":"luwu/type-checking.html#things-to-know","k":"section","t":"Things to know","g":"Type Checking","x":"Classes and traits are nominal types. Two classes with the same fields are still different types. Validators check string literals, like colors or sizes, with your own error messages. Type annotations describe values. They're separate from what type(x) returns."},{"p":"luwu/literal-types-and-validators.html","k":"page","t":"Literal Types and Validators","g":"Literal Types and Validators","x":"Some strings follow rules: hex colors, CSS sizes, routes, ids. Luwu can check those rules while you type. A wrong string becomes a type error with your own message."},{"p":"luwu/literal-types-and-validators.html#literal-types","k":"section","c":"type Direction = \"north\" | \"south\" | \"east\" | \"west\" const function walk(direction: Direction) print(`Walking {direction}`) end walk(\"north\") const function tag(name: literal<string>): string return `<{name}>` end print(tag(\"main\"))","t":"Literal types","g":"Literal Types and Validators","x":"A literal is a value written straight into the code, like \"red\" . A type can be a single literal. Calling walk(\"up\") is a type error. Luau has this too. Luwu adds literal<T> . It asks for a literal of type T, and keeps the exact value as the type. Passing a string variable to tag is a type error. The argument has to be written out."},{"p":"luwu/literal-types-and-validators.html#validators","k":"section","c":"type function HexColor(value: type): type if not value:is(\"singleton\") then return types.error(\"expected a literal like \\\"#3b5bdb\\\"\") end const text = value:value() if typeof(text) ~= \"string\" or string.sub(text, 1, 1) ~= \"#\" then return types.error(`'{tostring(text)}' is missing its '#'`) end const digits = string.sub(text, 2) if string.find(digits, \"[^%x]\") or (#digits ~= 3 and #digits ~= 6) then return types.error(`'{text}' isn't a hex color`) end return value end const function paint(color: HexColor<literal<string>>) print(`Painting with {color}`) end paint(\"#3b5bdb\") -- paint(\"3b5bdb\") is a type error: '3b5bdb' is missing its '#' -- paint(\"#12345\") is a type error: '#12345' isn't a hex color","t":"Validators","g":"Literal Types and Validators","x":"A validator is a type function that checks a literal. It runs while the code is checked, not at runtime. It gets the literal's type. It returns that type when the value is fine, or types.error with a message. The error shows up in your editor at the call."},{"p":"luwu/literal-types-and-validators.html#naming-a-validated-type","k":"section","c":"type function Percent(value: type): type if not value:is(\"singleton\") then return types.error(\"expected a literal like \\\"50%\\\"\") end const text = value:value() const number = typeof(text) == \"string\" and tonumber(string.match(text, \"^(%d+)%%$\")) if not number or number > 100 then return types.error(`'{tostring(text)}' isn't a percentage from 0% to 100%`) end return value end type Percentage = Percent<literal<string>> const function set_volume(volume: Percentage) print(`Volume: {volume}`) end const function set_brightness(brightness: Percentage) print(`Brightness: {brightness}`) end set_volume(\"80%\") set_brightness(\"100%\")","t":"Naming a validated type","g":"Literal Types and Validators","x":"Give the validated type a name to use it in many places:"},{"p":"luwu/literal-types-and-validators.html#in-tables-and-unions","k":"section","c":"type function Size(value: type): type if not value:is(\"singleton\") then return types.error(\"expected a literal like \\\"12px\\\"\") end const text = value:value() if typeof(text) ~= \"string\" or not string.match(text, \"^%d+px$\") then return types.error(`'{tostring(text)}' isn't a pixel size`) end return value end type Pixels = Size<literal<string>> | number type ButtonStyle = { width: Pixels?, height: Pixels?, } const function button(label: string, style: ButtonStyle) print(label, style.width, style.height) end button(\"Play\", { width = \"120px\", height = 40 }) -- button(\"Quit\", { width = \"120\" }) is a type error: '120' isn't a pixel size","t":"In tables and unions","g":"Literal Types and Validators","x":"Validated types work on table fields too. Each field is checked where it's written. A union can mix one validated literal with other types, like numbers:"},{"p":"luwu/literal-types-and-validators.html#things-to-know","k":"section","t":"Things to know","g":"Literal Types and Validators","x":"Validators only see literals. A string built at runtime can't be checked this way. Inside the function, the parameter is a plain string . Type functions are written in Luwu. They use the types library to inspect types."},{"p":"luwu/lints.html","k":"page","t":"Lints","g":"Lints","x":"Luwu expands Luau's built-in lint system with more than 40 new lints for Luau and Luwu code. They help you write more idiomatic and performant code, and catch mistakes the type checker can't see."},{"p":"luwu/lints.html#lint-control","k":"section","c":"--!lint ConstLocal local total = 0 for _, price in { 4, 8, 15 } do total += price end print(total)","t":"Lint control","g":"Lints","x":"Most lints are on by default. Turn one off for a file with --!nolint Name , or for one statement with @[nolint(Name)] above it. Turn on a lint that's off by default with --!lint Name : ConstLocal flags any local that's never reassigned and could be const . Because total is reassigned here, nothing is reported. All (not a lint): the name for every lint, as in --!nolint All or @[nolint(All)] , to turn them all off on purpose. BareNolint : --!nolint or @nolint with no lint names, which silences everything, probably by accident."},{"p":"luwu/lints.html#optimization-hints","k":"section","t":"Optimization hints","g":"Lints","x":"OptimizationHint is the parent of every hint below: code the compiler could optimize better if it were written differently. Turning it off turns them all off. LoopConcat : a string grown with .. inside a loop, which copies the whole string every iteration. It reports the cost for the loop nest (O(n²), O(n⁴), ...). InefficientTableInsert : table.insert(t, 1, v) in a loop, which shifts every element on each insert. InefficientTableRemove : table.remove(t, 1) in a loop, which shifts every element on each removal. MethodsNotInlined : code that keeps the compiler from proving an object's class, so its method calls can't be inlined: if cat then on a class-typed binding is only a nil check. if class.isinstance(cat, Cat) then proves the class for the branch. assert(cat) is only a nil check. assert(class.isinstance(cat, Cat)) proves the class for the rest of the block. several method calls through the same field ( self.pos:add(...) ). A field can't be proven in place: hoist it into a local and prove that once. FloorDivision : math.floor(a / b) , which is a division plus a call. a // b is one instruction. FenvDeoptimization : getfenv or setfenv , which turn off optimizations for the entir"},{"p":"luwu/lints.html#loops","k":"section","t":"Loops","g":"Lints","x":"RemoveWhileIterating : table.remove(t, i) while iterating t forwards by i , which skips the element after each removal. LoopVariableWrite : a loop variable that's written to but never read afterwards. IteratedTableWrite : adding or changing keys other than the current one while iterating a table, which can skip or repeat entries. ForeverLoop : a while or repeat loop whose condition nothing inside the loop can change. UselessLoop : a loop that only ever iterates once, because every path through it break s (or errors) on the first iteration. Loops that leave by return aren't reported, and neither is a for loop that leaves on its first iteration after using a loop variable."},{"p":"luwu/lints.html#values","k":"section","t":"Values","g":"Lints","x":"StringIndexZero : string functions called with index 0 ( string.byte(s, 0) , string.sub(s, 0, n) ). Strings start at 1. NewValueComparison : comparing against a table or function literal ( x == {} ), which is always false. TableTruthiness : testing a table's truthiness to check whether it's empty ( if t then ). Tables are always truthy. DiscardedResult : a builtin function, or a function marked @nodiscard , whose return values weren't used or explicitly discarded with _ . NilNoneComparison : comparing with nil where only none is possible, or the reverse. FloatIndex : xs[#xs / 2] , an index computed with / , which gives a float. VarargCast : f(... :: T) , which passes only the first value. LuaAndOr : a and b or c , which only acts like if a then b else c when b is truthy. SelfAssignment : x = x , which does nothing. DeadStore : a computed value that's overwritten before anything reads it. DeclareMismatch : declare x: T giving a global from the loaded definitions a different type."},{"p":"luwu/lints.html#expressive-control-flow","k":"section","t":"Expressive control flow","g":"Lints","x":"ReturnOnNextLine : a return in a do expression whose value starts on the next line, where it's easy to misread. OrContinue : x or continue in a module that uses continue as a name, where it reads that binding instead of continuing. OrReturnComma : f(x or return a, b) , where b is the next argument, not a second return value. BindingSwallowsCondition : if local x = f() and x > 1 , where the and is part of the bound value."},{"p":"luwu/lints.html#names","k":"section","t":"Names","g":"Lints","x":"KeywordShadow : a binding named after a contextual keyword ( continue , class , implements , declare , export , const ). BuiltinShadow : a binding that hides a builtin global ( type , typeof , table , ...). ReturnSelf : a trait method returning self typed as the trait, instead of Self ."},{"p":"luwu/lints.html#idiomatic-luwu","k":"section","t":"Idiomatic Luwu","g":"Lints","x":"ConstLocal : off by default. A local that's never reassigned, and could be const . LuaIterators : pairs(t) and ipairs(t) , which generalized iteration replaces. Pairs and Ipairs turn off each one on its own. LuaGuard : if not x then return end on one line, which Luwu can write as x or return . LuwuOnlyApi : a Luwu-only library function, like table.drop , used in a .luau file."},{"p":"luwu/lints.html#style","k":"section","t":"Style","g":"Lints","x":"Style is the group of layout lints. Turning it off turns all of them off, including ConstLocal , SameLineStatement and MultiLineStatement . OneLineStatement : if x then y end , while c do f() end or function f() return 1 end written on one line. OneLineGuard : if not x then return end on one line, in a Luau file. InlineOrLeave : x or return ending a line much longer than the lines around it. MisleadingIndentation : a do expression's block reaching lines indented like the code after it."},{"p":"luwu/better-hovers.html","k":"page","t":"Better Hovers","g":"Better Hovers","x":"Luwu's hovers target luwu-lsp, the language server we maintain alongside the language, and the Luwu VSCode/Code-OSS extension. Every hover on this page was copied unedited from luwu-lsp: point at a dotted underline to see one, or tap it on a touch screen."},{"p":"luwu/better-hovers.html#what-s-improved","k":"section","t":"What's improved","g":"Better Hovers","x":"Multiline types. Hovers print nested and recursive types over several lines, the way you'd write them in code, instead of on one long line. Large tables are cut short with their brackets still balanced. Related types, with links. Hovering a value also summarizes the classes and types its type refers to, each with a link to where it's declared. Verbosity levels decide how much of that is expanded (see More or less detail below). Overloads and unions, one per line. An overloaded function prints one signature per line, under a comment saying how many overloads it has, and a union of tables lays each member out on its own lines. A method called on a union of classes shows a single signature. Doc comments above types. Each type and field with a doc comment shows the first line of that comment right above it in the hover. References in doc comments, like [Health] or [math.max] , become links to their declaration or to the library docs."},{"p":"luwu/better-hovers.html#classes-at-a-glance","k":"section","c":"--- A cat that can be fed. class Cat(public const name: string, private hunger = 3) --- Feeds the cat, so it's less hungry. public function feed(self, amount: number = 1): Cat self.hunger = math.max(self.hunger - amount, 0) return self end end const nyla = Cat(\"Nyla\") nyla:feed(2)","t":"Classes at a glance","g":"Better Hovers","x":"Hover a class's name to see how to build one and what it holds, private members included. Hover an object of the class and you see only what you can use from outside. Access specifiers like public and private explain the rules they bring, so you don't need to look them up."},{"p":"luwu/better-hovers.html#traits","k":"section","c":"--- Something that takes damage and can run out of health. trait Health expect max_health: number health = 100 --- Takes `amount` off [Health], never going below zero, like [math.max] would. function damage(self, amount: number): Self self.health = math.max(self.health - amount, 0) return self end end --- A player in the arena. class Player(public const name: string) implements Health public max_health = 150 end const ada = Player(\"Ada\"):damage(30) print(ada.health)","t":"Traits","g":"Better Hovers","x":"A class's hover marks the members it gets from a trait, like -- from Health . A trait method returning Self shows the class you called it on: ada is a Player , not just Health . Doc comments link what they mention. [Health] jumps to the trait, and [math.max] links to the library docs."},{"p":"luwu/better-hovers.html#keywords-explain-themselves","k":"section","c":"const prices: { [string]: number? } = { apple = 1.25, pear = 0.8 } const total = do local sum = 0 for _, fruit in { \"apple\", \"kiwi\", \"pear\" } when const price = prices[fruit] do sum += price end give sum print(if total > 2 then \"pricey\" else \"cheap\")","t":"Keywords explain themselves","g":"Better Hovers","x":"Every keyword has a hover, Luwu's own included: do expressions, give and when . The same word gets a different hover when it means something else, like if as an expression."},{"p":"luwu/better-hovers.html#refinements","k":"section","c":"trait Named expect name: string end class Cat(name: string) implements Named end --- The name of anything that has one. const function name_of(thing: unknown): string? if class.implements(thing, Named) then return thing.name end return nil end const function tag(name: literal<string>): string return `<{name}>` end print(name_of(Cat(\"Nyla\")), tag(\"main\"))","t":"Refinements","g":"Better Hovers","x":"A function that narrows a type says so. Hover class.implements to see what it refines, then hover the refined value to see what it became. literal<T> and the other type functions explain themselves too."},{"p":"luwu/better-hovers.html#more-or-less-detail","k":"section","t":"More or less detail","g":"Better Hovers","x":"In your editor, a hover can show more or less. These commands change it for the rest of the session: More and Less ( alt+= and alt+- ): expand the types a hover mentions, or keep it short. Traits ( alt+t ): show the traits a class implements in full, below its hover. The luwu.hover.verbosity setting picks where each session starts."},{"p":"luwu/classes-and-traits.html","k":"page","t":"Classes and Traits","g":"Classes and Traits","x":"A class represents a concept from your program's domain. It groups that concept's data (its fields) with its behavior (its methods) and encapsulates the data to protect the class's invariants, the rules that must always hold. Each instance of a class, called an object, holds its own values for those fields. A trait is behavior that many classes share, written once and implemented by each of them. Classes and objects are primitives in Luwu, like numbers and strings. type() of a class is \"class\" . type() of an object is \"object\" ."},{"p":"luwu/classes-and-traits.html#from-metatables-to-classes","k":"section","c":"const Account = {} Account.__index = Account function Account.new(owner: string) return setmetatable({ owner = owner, balance = 0 }, Account) end export type Account = typeof(Account.new(...)) function Account.deposit(self: Account, amount: number) self.balance += amount end const account = Account.new(\"Ada\") account:deposit(50) print(account.balance) class Account(owner: string) balance = 0 function deposit(self, amount: number) self.balance += amount end end const account = Account(\"Ada\") account:deposit(50) print(account.balance)","t":"From metatables to classes","g":"Classes and Traits","x":"In Luau, objects are usually tables with a metatable. Each one needs some setup code: That's well-typed Luau. The type comes from typeof(Account.new(...)) . Each method takes self: Account by hand. In Luwu, the same thing is a class:"},{"p":"luwu/classes-and-traits.html#type-checking","k":"section","t":"Type checking","g":"Classes and Traits","x":"Metatables are hard for the type checker to follow, and types and autocomplete often break on them. With a class, the checker knows every field and method of every object, and a misspelled field is a type error instead of a silent nil. Classes and traits are nominally typed: what matters is the name, not the shape. Two classes with the same fields are still different types, and one can't be passed where the other is expected. A trait's name is a type too, and an object of any class that implements the trait fits it. Metatables still work, and Luwu doesn't ask you to give them up. Luwu still types tables with metatables structurally like Luau but checks them better through improvements like type references and method calls on union types."},{"p":"luwu/classes-and-traits.html#performance","k":"section","t":"Performance","g":"Classes and Traits","x":"Classes are also faster than metatable objects. Objects take less memory than tables, and reading or writing a field skips the key lookup a table needs. At --!optimize 2 , Luwu can also copy small methods straight into the code that calls them. You don't need to do anything special to get this: write classes, and the compiler does the rest. See Performance Innovations →"},{"p":"luwu/classes-and-traits.html#inheritance-through-traits","k":"section","t":"Inheritance through traits","g":"Classes and Traits","x":"Upstream Luau is adding classical inheritance through open class and extends . Luwu keeps the useful parts of inheritance and calls them traits. A trait gives classes shared methods with default implementations they can override, lists members each class is expected to provide, and can build on other traits. What Luwu leaves out is the confusing part of classical inheritance. Building an object only ever runs its own class's constructor. There's no is-a identity either: an object belongs to exactly one class, and class.isinstance checks that class alone. Whether an object has some trait's behavior is a separate question, answered by class.implements . Traits are covered further down."},{"p":"luwu/classes-and-traits.html#classes","k":"section","t":"Classes","g":"Classes and Traits"},{"p":"luwu/classes-and-traits.html#your-first-class","k":"section","c":"class Dog(name: string, age: number) function bark(self) print(`{self.name} barked!`) end function birthday(self) self.age += 1 end end const oreo = Dog(\"Oreo\", 3) oreo:bark() oreo:birthday() print(oreo.age)","t":"Your first class","g":"Classes and Traits","x":"The parameters after the class name are its primary constructor. Each parameter becomes a field of the object. Functions that take self are methods. You call them with : . Calling a class like a function builds a new object. Passing the wrong number or type of arguments is a type error."},{"p":"luwu/classes-and-traits.html#plain-old-data-pod-classes","k":"section","c":"class Settings volume = 0.8 fullscreen = false player_name = \"Player\" end const defaults = Settings() const custom = Settings { fullscreen = true, player_name = \"Ada\" } print(defaults.volume, custom.fullscreen, custom.player_name) class Inventory items: { string } = {} end const a = Inventory() const b = Inventory() table.insert(a.items, \"sword\") print(#a.items, #b.items)","t":"Plain old data (POD) classes","g":"Classes and Traits","x":"Some classes just hold data, like a named table or a struct. Luwu calls these plain old data (POD) classes. Give each field a default value, and leave out the constructor. Then build objects from a table with the POD constructor. Fields you leave out keep their defaults. Default values are created fresh for every object. Two objects never share a default table by accident."},{"p":"luwu/classes-and-traits.html#static-functions","k":"section","c":"class Temperature(celsius: number) function from_fahrenheit(fahrenheit: number): Temperature return Temperature((fahrenheit - 32) * 5 / 9) end function describe(self): string return `{self.celsius}°C` end end print(Temperature.from_fahrenheit(212):describe())","t":"Static functions","g":"Classes and Traits","x":"A function without self belongs to the class itself. Call it with a dot. Static functions are a good place for alternative ways to build an object."},{"p":"luwu/classes-and-traits.html#computed-fields","k":"section","c":"class Username(raw: string) text = string.lower((string.gsub(raw, \"%s+\", \"_\"))) end const name = Username(\"Ada Lovelace\") print(name.text, name.raw)","t":"Computed fields","g":"Classes and Traits","x":"A field's default can use the constructor's parameters. That's how you clean up or derive data on the way in. The parameter stays a field too: name.raw is still there."},{"p":"luwu/classes-and-traits.html#constructors-with-init","k":"section","c":"class Point x: number y: number function __init(self, text: string) const x, y = string.match(text, \"^(%-?%d+),(%-?%d+)$\") self.x = tonumber(x) or 0 self.y = tonumber(y) or 0 end end const point = Point(\"3,4\") print(point.x, point.y)","t":"Constructors with __init","g":"Classes and Traits","x":"Add an __init function when building an object needs custom logic. Luwu creates the object, then calls __init with it and your arguments. Reach for it when: the constructor takes parameters that shouldn't become fields fields are computed from the arguments over several steps construction calls other functions, or validates its input the constructor needs to yield, like waiting on a file or a network request This point is built from text like \"3,4\". It keeps x and y, but not the text: A class has either a primary constructor or __init , not both."},{"p":"luwu/classes-and-traits.html#public-private-and-const","k":"section","c":"class BankAccount( public const owner: string, private balance: number = 0 ) public function deposit(self, amount: number) if amount > 0 then self.balance += amount end end public function get_balance(self): number return self.balance end end const account = BankAccount(\"Ada\") account:deposit(50) account:deposit(-10) print(account.owner, account:get_balance())","t":"Public, private and const","g":"Classes and Traits","x":"Mark a member private to keep it inside the class. Code outside the class can't read or change it. Trying is a type error, and an error at runtime. Mark a field const when it should never change after the object is built. Once one member has public or private, every member needs one. Only the class's own methods can change the balance. Every deposit goes through the same check."},{"p":"luwu/classes-and-traits.html#protecting-invariants","k":"section","c":"const colors = require(\"@std/io/colors\") const EMPTY = vector.create(243, 139, 168) const FULL = vector.create(166, 227, 161) class Health private ( private current: number, public const max_health: number ) public function full(max_health: number): Health return Health(max_health, max_health) end private function clamped(current: number, max_health: number): Health if math.isnan(current) then error(\"health can't be NaN\", 3) end return Health(math.clamp(current, 0, max_health), max_health) end public function __add(self, amount: number): Health return Health.clamped(self.current + amount, self.max_health) end public function __sub(self, amount: number): Health return Health.clamped(self.current - amount, self.max_health) end public function __eq(self, other: Health): boolean return self.current == other.current end public function __lt(self, other: Health): boolean return self.current < other.current end public function __le(self, other: Health): boolean return self.current <= other.current end public function __tostring(self): string const ratio = self.current / self.max_health const filled = math.round(ratio * 20) const bar = colors.rgb(vector.lerp(EMPTY, FULL, ratio), string.rep","t":"Protecting invariants","g":"Classes and Traits","x":"Some data is only valid when certain properties always hold: health stays between 0 and its maximum, an age is never negative, a position is never NaN. Those properties are the class's invariants, and encapsulation is how a class protects them. When the fields are private and every change goes through the class's own methods, no code outside it can leave the data in an invalid state. This Health class represents a player's health points. Its constructor and current are private, every change goes through clamped , and its metamethods let you use + , - , == and < on it directly. Printing it draws a healthbar: The healthbar's colors come from seal's @std/io/colors library. Save the example as health.luwu and run it with seal : ████████████████████ 100/100 ███████ ░░░░░░░░░░░░░ 35/100 ████████████████████ 100/100, true ██ ░░░░░░░░░░░░░░░░░░ 10/100, true Overhealing by 500 stops at 100/100 because every result passes through math.clamp . From outside the class, hp.current = -20 is a type error and a runtime error, and Health(-5, "},{"p":"luwu/classes-and-traits.html#operators-on-objects","k":"section","c":"type Currency = \"USD\" | \"EUR\" | \"GBP\" class Money private ( private const units: number, private const cents: number, public const currency: Currency ) public function usd(units: number, cents: number): Money return Money.of(units, cents, \"USD\") end public function eur(units: number, cents: number): Money return Money.of(units, cents, \"EUR\") end public function gbp(units: number, cents: number): Money return Money.of(units, cents, \"GBP\") end private function of(units: number, cents: number, currency: Currency): Money if units % 1 ~= 0 or cents % 1 ~= 0 or units < 0 or cents < 0 or cents > 99 then error(\"expected whole units and 0 to 99 cents\", 3) end return Money(units, cents, currency) end private function check_currency(self, other: Money) if self.currency ~= other.currency then error(`can't mix {self.currency} and {other.currency}`, 3) end end public function __add(self, other: Money): Money self:check_currency(other) const cents = self.cents + other.cents const units = self.units + other.units + cents // 100 return Money(units, cents % 100, self.currency) end public function __eq(self, other: Money): boolean return self.units == other.units and self.cents == other.cents and sel","t":"Operators on objects","g":"Classes and Traits","x":"Metamethods let your objects work with operators like + and == . Name a method after the metamethod. Money keeps whole units and cents in separate fields because a floating point number can't hold most fractions exactly ( 0.1 + 0.2 is 0.30000000000000004 ). Its constructor and fields are private, and every amount comes from Money.usd , Money.eur or Money.gbp . Those reject negative amounts and fractions of a cent before an object ever exists."},{"p":"luwu/classes-and-traits.html#checking-what-an-object-is","k":"section","c":"class Circle(radius: number) end class Square(side: number) end const function area(shape: Circle | Square): number if class.isinstance(shape, Circle) then return math.pi * shape.radius ^ 2 end return shape.side ^ 2 end print(area(Circle(1)), area(Square(3))) print(class.name(Square(3)))","t":"Checking what an object is","g":"Classes and Traits","x":"class.isinstance tells you whether a value is an object of a class. Inside the check, Luwu knows the value's type."},{"p":"luwu/classes-and-traits.html#traits","k":"section","t":"Traits","g":"Classes and Traits","x":"Traits are how classes inherit behavior in Luwu. A trait lists what it expects from a class, and what it gives the class in return. A class can implement as many traits as it needs."},{"p":"luwu/classes-and-traits.html#sharing-behavior","k":"section","c":"trait Lootable expect loot: { string } function drop(self): { string } const dropped = self.loot self.loot = {} return dropped end end class Chest(loot: { string }) implements Lootable end class Slime(hp: number, loot: { string }) implements Lootable end const chest = Chest({ \"gold\", \"map\" }) const slime = Slime(5, { \"goo\" }) print(#chest:drop(), #chest:drop(), slime:drop()[1])","t":"Sharing behavior","g":"Classes and Traits","x":"Here, Lootable gives any class a working drop method. It only asks the class for a loot list. Both classes get the trait's methods without writing them again."},{"p":"luwu/classes-and-traits.html#expected-members","k":"section","c":"trait Describable expect const name: string expect function details(self): string function describe(self): string return `{self.name}: {self:details()}` end end class Sword implements Describable const name = \"Iron sword\" damage = 7 function details(self): string return `deals {self.damage} damage` end end print(Sword():describe())","t":"Expected members","g":"Classes and Traits","x":"expect lists what an implementing class must provide: fields, functions or both. Leaving one out is a type error, and an error when the class is created."},{"p":"luwu/classes-and-traits.html#overriding-a-trait-s-function","k":"section","c":"trait Greeting function greet(self): string return \"Hello!\" end end class Pirate implements Greeting function greet(self): string return Greeting.greet(self) .. \" Arr!\" end end print(Pirate():greet())","t":"Overriding a trait's function","g":"Classes and Traits","x":"A class can replace a trait's function with its own version. The class can still reach the trait's version with Trait.function(self) . The override must take the same arguments the trait's version does. Extra arguments must be optional."},{"p":"luwu/classes-and-traits.html#building-on-other-traits","k":"section","c":"trait Named expect const name: string end trait Speaker needs Named function introduce(self): string return `I'm {self.name}.` end end class Robot implements Speaker const name = \"R2\" end print(Robot():introduce())","t":"Building on other traits","g":"Classes and Traits","x":"A trait can needs another trait. Implementing it implements both."},{"p":"luwu/classes-and-traits.html#final-members","k":"section","c":"trait Shape expect function area(self): number final function total_area(shapes: { Shape }): number local total = 0 for _, shape in shapes do total += shape:area() end return total end end class Rectangle(width: number, height: number) implements Shape function area(self): number return self.width * self.height end end class Circle(radius: number) implements Shape function area(self): number return math.pi * self.radius ^ 2 end end print(Shape.total_area({ Rectangle(2, 3), Circle(1) }))","t":"Final members","g":"Classes and Traits","x":"Mark a trait's member final when classes must not replace it. A final function without self is a static function on the trait, for helpers that belong with it."},{"p":"luwu/classes-and-traits.html#traits-with-parameters","k":"section","c":"trait Stackable(max_stack: number = 64) count = 1 function add(self, amount: number): number const room = self.max_stack - self.count const added = math.min(room, amount) self.count += added return amount - added end end class Arrow implements Stackable end class Potion implements Stackable(8) end print(Arrow():add(100), Potion():add(100))","t":"Traits with parameters","g":"Classes and Traits","x":"A trait can take parameters, like a class's constructor. The class passes them when it implements the trait."},{"p":"luwu/classes-and-traits.html#working-with-any-implementer","k":"section","c":"trait Animal -- Animal is trait<Animal> expect species: string end class Cat( -- Cat is class<Animal> name: string, age: number ) implements Animal species = \"Felis catus\" end const nyla = Cat(\"Nyla\", 14) -- nyla is Animal trait Animal expect species: string end class Cat(name: string) implements Animal species = \"Felis catus\" end class Dog(name: string) implements Animal species = \"Canis familiaris\" end class Rock() end const function describe(thing: unknown): string if class.implements(thing, Animal) then return `an animal of species {thing.species}` elseif class.isinstance(thing, Rock) then return \"a rock\" end return \"something else\" end print(describe(Cat(\"Nyla\"))) print(describe(Dog(\"Rex\"))) print(describe(Rock()))","t":"Working with any implementer","g":"Classes and Traits","x":"A trait is also a type. { Shape } is a list of anything that implements Shape . Trait is any object whose class implements Trait , class<Trait> is the type of the class value of any class that implements Trait , and trait<Trait> is the type of the trait value itself. This might be confusing, so here's an example: class.isinstance asks whether a value is an object of one exact class, while class.implements asks whether the value's class implements a trait. Inside either check Luwu narrows the value's type. Once describe knows it has an Animal , reading thing.species type checks: Written with only class.isinstance , describe would need a check for Cat , another for Dog and one more for every animal class anyone adds later, even in code it has never seen. A single class.implements check covers them all. class.isinstance only takes classes, and when it's given a trait luwu-analyze reports Expected this to be a class, got trait 'Animal' ."},{"p":"luwu/classes-and-traits.html#traits-as-factories","k":"section","c":"const components: { [string]: class<Component>? } = {} trait Component expect function __init(self) expect function render(self): string function __create(name: string): Component const cls = components[name] or error(`no component called {name}`, 2) return cls() end final function register(cls: class<Component>) components[class.name(cls)] = cls end end class Button() implements Component function render(self): string return \"<button>Save</button>\" end end class Spinner() implements Component function render(self): string return `<div class=\"spinner\"></div>` end end Component.register(Button) Component.register(Spinner) -- names a parser found in the page's data-element attributes for _, name in { \"Spinner\", \"Button\" } do print(Component(name):render()) end","t":"Traits as factories","g":"Classes and Traits","x":"Sometimes code has to build an object without knowing its class. chimera, the library this site is built with, parses HTML back into objects: it reads each component's name from attributes like data-element=\"Card\" , and apps register components chimera has never heard of. A trait can build those objects. Give the trait a __create function and calling the trait like a class runs it to pick a concrete class and return a new object of that class. This Component trait keeps a registry of class<Component> values by class name. Each component class is registered once with Component.register , and Component(\"Button\") then builds a Button : Only traits that define __create can be called. Calling the Animal trait from earlier raises trait 'Animal' can't be called: it has no '__create' ."},{"p":"luwu/classes-and-traits.html#things-to-know","k":"section","t":"Things to know","g":"Classes and Traits","x":"Classes and traits are defined at the top level of a file. Objects have exactly the fields their class lists. Reading a missing field is an error. Objects compare by identity unless the class defines __eq . A class's name is also a type: an object of that class."},{"p":"luwu/classes-and-traits/performance-innovations.html","k":"page","t":"Performance Innovations","g":"Performance Innovations","x":"How Luwu makes classes fast, and when each optimization applies."},{"p":"luwu/classes-and-traits/performance-innovations.html#inline-fields","k":"section","t":"Inline fields","g":"Performance Innovations","x":"An object stores its fields inline, in an order its class fixes up front, instead of in a hash table that grows as keys are added. That makes objects smaller too: an object with two number fields takes 88 bytes, where a table holding the same fields takes 128."},{"p":"luwu/classes-and-traits/performance-innovations.html#constant-offset-field-access","k":"section","t":"Constant-offset field access","g":"Performance Innovations","x":"Because the order is fixed, the compiler turns a field access into a constant offset. Inside a method, self.health compiles to a GETOBJECTMEMBER instruction ( SETOBJECTMEMBER for writes) that goes straight to the field's slot, with no key lookup and no cache to check. With native code generation, a field read takes about 0.9 nanoseconds against 2.0 for a table, and a write about 0.3 against 4.5. Reading the same field twice in a row costs one read, since constant propagation reuses the first."},{"p":"luwu/classes-and-traits/performance-innovations.html#proving-what-self-is","k":"section","t":"Proving what self is","g":"Performance Innovations","x":"The compiler only takes these shortcuts when it can prove what self is. Every method starts with a self check that raises an error when it's called on the wrong kind of value. Past that check, self is proven to be an object of the method's class, as long as the method never reassigns it. Type annotations deliberately don't count as proof because a wrong one would read the wrong memory instead of failing with an error."},{"p":"luwu/classes-and-traits/performance-innovations.html#method-inlining","k":"section","t":"Method inlining","g":"Performance Innovations","x":"At optimization level 2 ( --!optimize 2 ), Luwu also inlines method calls. The compiler copies the body of a small method into its caller and removes the call entirely. This is where most of the speed of classes comes from. Inlining follows the same rule of proof: a call inlines when the compiler can prove the receiver's class. That covers self:method() inside a class, an object the same code just constructed, and a value checked with class.isinstance in an if or an assert . An inlined body still runs its self check, and still fails loudly on the wrong kind of object. Hot code runs fastest in the same module as the classes it uses because methods only inline within a module."},{"p":"luwu/classes-and-traits/performance-innovations.html#trusting-type-annotations","k":"section","t":"Trusting type annotations","g":"Performance Innovations","x":"Proving every receiver gets tedious once objects hold other objects. The --!trust directive lets a file trust its type annotations instead: a parameter, local or field annotated with a class is then enough to pick the method to inline. Trust never lets wrong code run quietly because the inlined self check turns a lying annotation into a runtime error. --!trust is still experimental, and isn't turned on by default yet."},{"p":"luwu/classes-and-traits/performance-innovations.html#construction-and-type-tests","k":"section","t":"Construction and type tests","g":"Performance Innovations","x":"Building and testing objects is cheap too. Constructing an object compiles to a single NEWOBJECT instruction with no temporary table and no function call. class.isinstance compiles to one fused test-and-branch instruction that native code drops entirely when the class is already known."},{"p":"luwu/destructuring.html","k":"page","c":"const player = { name = \"Ada\", level = 12, class = \"Mage\" } local name = player.name local level = player.level print(name, level) const player = { name = \"Ada\", level = 12, class = \"Mage\" } const .{ name, level } = player print(name, level)","t":"Destructuring","g":"Destructuring","x":"Destructuring pulls several fields out of a table in one line. In Luau, you write each name twice: In Luwu, you list the names once: .{ name, level } reads player.name and player.level . The table is evaluated once."},{"p":"luwu/destructuring.html#renaming-with-as","k":"section","c":"const response = { status = 200, body = \"ok\" } const .{ status as code, body as text } = response print(code, text)","t":"Renaming with as","g":"Destructuring","x":"Use as to give a field a different local name. The field's name comes first."},{"p":"luwu/destructuring.html#nested-tables","k":"section","c":"const user = { name = \"Ada\", address = { city = \"London\", country = \"UK\" }, } const .{ name, address.{ city } } = user print(name, city, address.country) const user = { address = { city = \"London\", country = \"UK\" } } const .{ address as .{ city, country } } = user print(city, country)","t":"Nested tables","g":"Destructuring","x":"Patterns nest. Add a dot and braces after a name to reach inside it. address.{ city } binds both address and city . To skip address , rename it into a pattern:"},{"p":"luwu/destructuring.html#keeping-the-whole-value","k":"section","c":"const function load_config() return { width = 1280, height = 720, title = \"Game\" } end const config.{ width, height } = load_config() print(width * height, config.title)","t":"Keeping the whole value","g":"Destructuring","x":"Put a name before the braces to keep the whole table too."},{"p":"luwu/destructuring.html#imports","k":"section","c":"const .{ readfile, writefile } = require(\"@std/fs\") const fs.{ path } = require(\"@std/fs\") print(typeof(readfile), typeof(writefile), typeof(path.join), typeof(fs)) const process = require(\"@std/process\") type .{ RunResult } = process const function succeeded(result: RunResult): boolean return result.ok end print(typeof(succeeded))","t":"Imports","g":"Destructuring","x":"Destructuring shines at the top of a file. Take just what you need from a module. type .{ ... } = module does the same for a module's exported types:"},{"p":"luwu/destructuring.html#loops","k":"section","c":"const books = { { title = \"Dune\", year = 1965 }, { title = \"Hyperion\", year = 1989 }, } for _, .{ title, year } in books do print(`{title} came out in {year}`) end","t":"Loops","g":"Destructuring","x":"Destructure each item in a for loop's header."},{"p":"luwu/destructuring.html#in-if-local","k":"section","c":"const function lookup(id: number): { name: string?, email: string? } return if id == 1 then { name = \"Ada\", email = \"ada@example.com\" } else {} end if const .{ name, email } = lookup(1) then print(`Mail {name} at {email}`) end","t":"In if local","g":"Destructuring","x":"A destructuring binding in an if local passes when every name it binds is truthy."},{"p":"luwu/destructuring.html#building-tables-with","k":"section","c":"const name = \"Ada\" const email = \"ada@example.com\" const user = .{ name, email, verified = true } print(user.name, user.email, user.verified) const function stats(numbers: { number }) local min, max, sum = math.huge, -math.huge, 0 for _, n in numbers do min = math.min(min, n) max = math.max(max, n) sum += n end const average = sum / #numbers return .{ min, max, average } end const .{ min, max, average } = stats({ 4, 8, 15, 16, 23, 42 }) print(min, max, average) class Color r = 0 g = 0 b = 0 end const r, g, b = 255, 128, 0 const orange = Color.{ r, g, b } print(orange.r, orange.g, orange.b)","t":"Building tables with .{ }","g":"Destructuring","x":"The same braces work the other way around. A bare name becomes a field of the same name. It's handy for returning several values by name: It also builds plain old data (POD) classes:"},{"p":"luwu/destructuring.html#things-to-know","k":"section","t":"Things to know","g":"Destructuring","x":"Destructuring reads fields by name. A missing field on a plain table gives nil. On a class object, a missing field is an error, like any other read. Function parameters can't be destructured. Destructure inside the function instead. You can't assign to a pattern. .{ a, b } = t without const or local is an error."},{"p":"luwu/none.html","k":"page","t":"The none Primitive","g":"The none Primitive","x":"none is a value that means \"intentionally empty\". It behaves like nil , except that you can store it in a table."},{"p":"luwu/none.html#why-nil-isn-t-enough","k":"section","c":"local list = { \"first\", nil, \"third\" } print(#list) -- 3 or 1, depending on how the table was built const list = { \"first\", none, \"third\" } print(#list) print(list[2] == none) const json = require(\"@std/json\") const user = json.decode('{\"name\": \"Ada\", \"nickname\": null}') print(user.nickname == none) print(user.nickname or \"no nickname\") print(json.raw(user))","t":"Why nil isn't enough","g":"The none Primitive","x":"In Luau, setting a table field to nil deletes it. The field is gone, not empty. In a list, nil leaves a hole. Then the length operator can't be trusted. With none , the slot stays filled: JSON shows the problem best. JSON has null, and Luau has no value that can stand for it. Decode {\"nickname\": null} into a Luau table, and the nickname key is simply gone. Encode that table again, and the field is missing from the output. The data doesn't round-trip. So every Luau runtime invents its own workaround: Lune decodes null as nil. It has no way to write null back out. Zune decodes null as a JsonValue.Null table, if you pass preserve_null . Lute decodes null as json.null , a sentinel made with newproxy . seal 0.8 used json.null() , a special userdata value. Code written against one runtime's sentinel breaks on every other runtime. The sentinels are all truthy, too: if user.nickname then treats a null nickname as a real one. In Luwu, JSON null is just none . seal decodes null as none and encodes none as null. The data round-trips, and none is falsy like nil:"},{"p":"luwu/none.html#how-none-behaves","k":"section","c":"const settings: { [string]: (string | none)? } = { theme = \"dark\", font = none } print(settings.font == none) print(settings.missing == nil) print(settings.font or \"default font\") for key, value in settings do print(key, value) end","t":"How none behaves","g":"The none Primitive","x":"none is falsy, like nil and false. none == none is true. none == nil is false. type(none) is \"none\". Storing none in a table keeps the key."},{"p":"luwu/none.html#use-cases","k":"section","c":"type Person = { first: string, middle: string | none, last: string } const ada: Person = { first = \"Ada\", middle = none, last = \"Lovelace\" } const function full_name(person: Person): string if person.middle ~= none then return `{person.first} {person.middle} {person.last}` end return `{person.first} {person.last}` end print(full_name(ada)) const show_admin = false const menu = { \"Home\", \"Profile\", if show_admin then \"Admin\" else none, \"Log out\", } for _, item in menu when item ~= none do print(item) end print(#menu)","t":"Use cases","g":"The none Primitive","x":"none fits anywhere \"no value\" is real data. A form might have a middle name field that's empty on purpose: A list can mark items as left out without leaving holes:"},{"p":"luwu/none.html#listing-every-field","k":"section","c":"class Profile name = \"Ada\" nickname: string? = nil level = 12 end const fields = class.fields(Profile()) print(fields.name, fields.nickname, fields.level) print(fields.nickname == none) const function snapshot(values: { [string]: string? }, keys: { string }): { [string]: string | none } return { for _, key in keys give [key] = values[key] or none } end const form = snapshot({ email = \"ada@example.com\" }, { \"email\", \"phone\" }) for key, value in form do print(key, value) end","t":"Listing every field","g":"The none Primitive","x":"class.fields gives you an object's public fields as a table. A field that's nil shows up as none . Every field name is still there, even the empty ones. This prints Ada, none, 12 . With nil, the nickname would vanish from the table. The checker knows it too: the nickname field's type is string | none . Your own functions can work the same way. This one reports a form, keeping the empty fields: The phone field is listed as none . Code reading the report knows it was left empty."},{"p":"luwu/none.html#things-to-know","k":"section","t":"Things to know","g":"The none Primitive","x":"Optional types read T? for nil. Write T | none for none. Comparing none with < or > is an error, like nil. none is a global value. A local named none would hide it."},{"p":"luwu/expressive-control-flow.html","k":"page","t":"Expressive Control Flow","g":"Expressive Control Flow","x":"Luwu adds a few control flow tools that Luau doesn't have. They let you check a value right where you get it. Code needs fewer nested ifs and fewer temporary variables."},{"p":"luwu/expressive-control-flow.html#if-local","k":"section","c":"const scores: { [string]: number? } = { ada = 92 } local score = scores[\"ada\"] if score then print(`Ada scored {score}`) end const scores: { [string]: number? } = { ada = 92 } if local score = scores[\"ada\"] then print(`Ada scored {score}`) end type User = { name: string } const users: { User } = { { name = \"Ada\" }, { name = \"Grace\" } } const function find(name: string): User? for _, user in users do if user.name == name then return user end end return nil end if const user = find(\"Grace\") then print(`Found {user.name}`) elseif const fallback = find(\"Ada\") then print(`Using {fallback.name} instead`) else print(\"Nobody here\") end","t":"if local","g":"Expressive Control Flow","x":"In Luau, you often get a value, then check that it exists: With if local , you bind the value inside the condition: The branch runs when the value is truthy: not nil , false or none . score only exists inside the branch. It can't leak into the code after it. Use if const when the branch won't reassign the value. Most of the time, that's what you want."},{"p":"luwu/expressive-control-flow.html#when-chains","k":"section","c":"const players: { [string]: { level: number, guild: string? } } = { ada = { level = 12, guild = \"Builders\" }, grace = { level = 3 }, } const function invite(id: string) if const player = players[id] when player.level >= 10 when const guild = player.guild then print(`{id} can lead raids for {guild}`) else print(`{id} can't lead raids yet`) end end invite(\"ada\") invite(\"grace\") const function parse_point(text: string): { x: number?, y: number? } const x, y = string.match(text, \"^(%-?%d+),(%-?%d+)$\") return { x = tonumber(x), y = tonumber(y) } end if const .{ x, y } = parse_point(\"3,4\") then print(x + y) end","t":"when chains","g":"Expressive Control Flow","x":"Add more checks with when . Each clause must pass for the branch to run. A clause can be a plain condition or another binding. Later clauses can use earlier bindings. Clauses run left to right. The first one that fails stops the chain. A binding clause can destructure. Every name it binds must be truthy."},{"p":"luwu/expressive-control-flow.html#if-const-in-expressions","k":"section","c":"const nicknames: { [string]: string? } = { grace = \"Amazing Grace\" } const function display_name(id: string): string return if const nickname = nicknames[id] then nickname else id end print(display_name(\"grace\"), display_name(\"ada\"))","t":"if const in expressions","g":"Expressive Control Flow","x":"if local and if const also work in if-else expressions."},{"p":"luwu/expressive-control-flow.html#when-in-loops","k":"section","t":"when in loops","g":"Expressive Control Flow","x":"Luwu's loops take when chains too."},{"p":"luwu/expressive-control-flow.html#while-local","k":"section","c":"const jobs = { \"build\", \"test\", \"deploy\" } while const job = table.remove(jobs, 1) do print(`Running {job}`) end const lines = { \"name = Ada\", \"level = 12\", \"\", \"ignored = true\" } local index = 0 while const line = lines[index + 1] when line ~= \"\" do index += 1 print(line) end","t":"while local","g":"Expressive Control Flow","x":"while local binds a fresh value on every pass. The loop ends as soon as the chain fails. Add a when clause to stop early:"},{"p":"luwu/expressive-control-flow.html#for-when","k":"section","c":"const inventory = { { name = \"Arrow\", count = 24 }, { name = \"Potion\", count = 0 }, { name = \"Rope\", count = 2 }, } for _, item in inventory when item.count > 0 do print(`{item.name} x{item.count}`) end const prices: { [string]: number? } = { apple = 1.25, pear = 0.8 } const basket = { \"apple\", \"kiwi\", \"pear\" } for _, fruit in basket when const price = prices[fruit] do print(`{fruit} costs {price}`) end for n = 1, 20 when n % 3 == 0 and n % 2 == 1 do print(n) end","t":"for ... when","g":"Expressive Control Flow","x":"A when chain after a for loop's header skips the items that fail it. No more wrapping the whole loop body in an if. Bindings work here too, and so do numeric loops:"},{"p":"luwu/expressive-control-flow.html#do-expressions","k":"section","c":"const price, quantity = 4.5, 12 local subtotal = price * quantity local discount = if quantity >= 10 then subtotal * 0.1 else 0 local total = subtotal - discount print(total) const price, quantity = 4.5, 12 const total = do const subtotal = price * quantity const discount = if quantity >= 10 then subtotal * 0.1 else 0 give subtotal - discount print(total) const words = { \"luwu\", \"classes\", \"traits\" } const longest = do local best = \"\" for _, word in words do if #word > #best then best = word end end give best print(longest) const players = { { name = \"Ada\", online = false }, { name = \"Grace\", online = true }, { name = \"Alan\", online = true }, } const host = do for _, player in players do if player.online then give player.name end end give \"nobody\" print(host)","t":"do expressions","g":"Expressive Control Flow","x":"Sometimes one value takes several statements to work out. A do expression runs a block and gives back a value. give ends the block and produces its value. There's no end . In Luwu we prefer do / give blocks over temporary and intermediate variables. Scoping the computation inside the expression that produces a value makes obvious what the code is actually building up. A do expression also fits several statements where only an expression goes, like do print(x) give x to debug a value in place. Unlike a function call that abstracts the same computation, it's always inlined and costs nothing. In Luau, the temporaries sit next to the result, and stay in scope for the rest of the function: With a do expression, subtotal and discount live inside the block that computes total . Readers see at a glance that they exist only for it: A loop that builds up one value works the same way: The temporary best stays inside the block. longest can be const. A give can also leave the block early, like a return . This one stops at the first player who is online, and only falls back to the last line when nobody is:"},{"p":"luwu/expressive-control-flow.html#or-return-or-continue-or-break","k":"section","c":"const prices: { [string]: number? } = { apple = 1.25, pear = 0.8 } const function total(order: { [string]: number? }): number? local sum = 0 for item, count in order do const price = prices[item] or return nil sum += price * count end return sum end print(total({ apple = 4 })) print(total({ apple = 1, kiwi = 2 })) const entries = { \"hp=10\", \"broken\", \"mp=4\", \"stop\", \"xp=99\" } for _, entry in entries do if entry == \"stop\" then break end const key, value = string.match(entry, \"^(%a+)=(%d+)$\") if not key or not value then continue end print(key, value) end for _, entry in entries do entry ~= \"stop\" or break const key, value = string.match(entry, \"^(%a+)=(%d+)$\") key and value or continue print(key, value) end","t":"or return, or continue, or break","g":"Expressive Control Flow","x":"Guard clauses check for a missing value and leave early, and or return writes one in a single line. After the guard, Luwu knows price isn't nil. or continue and or break work the same way inside loops: Both loops print the same thing. The second one reads top to bottom with every exit at the left edge."},{"p":"luwu/table-comprehensions.html","k":"page","c":"const numbers = { 1, 2, 3, 4 } local doubled = {} for _, n in numbers do table.insert(doubled, n * 2) end print(#doubled) const numbers = { 1, 2, 3, 4 } const doubled = { for _, n in numbers give n * 2 } print(#doubled)","t":"Table Comprehensions","g":"Table Comprehensions","x":"A table comprehension builds a new table from a loop, in one expression. In Luau, you'd create an empty table and fill it: In Luwu, you write the loop inside the table: give says what goes into the table for each item. Comprehensions are also faster. Luwu sizes the table up front. It never has to grow while filling."},{"p":"luwu/table-comprehensions.html#filtering-with-when","k":"section","c":"const scores: { [string]: number? } = { ada = 92, alan = 67, grace = 88 } const passed = { for name, score in scores when score >= 70 give name } print(#passed) const prices: { [string]: number? } = { apple = 1.25, pear = 0.8 } const basket = { \"apple\", \"kiwi\", \"pear\" } const costs = { for _, fruit in basket when const price = prices[fruit] give price * 2 } print(costs[1], costs[2])","t":"Filtering with when","g":"Table Comprehensions","x":"Add when clauses to skip items. They work just like in if local. A when clause can bind a value for the give to use:"},{"p":"luwu/table-comprehensions.html#building-maps","k":"section","c":"const players = { \"Ada\", \"Grace\", \"Alan\" } const name_lengths = { for _, player in players give [player] = #player } print(name_lengths.Grace) const words = { \"red\", \"blue\", \"red\", \"green\", \"red\" } const counts = { for _, word in words give [word] += 1 } print(counts.red, counts.blue)","t":"Building maps","g":"Table Comprehensions","x":"Give [key] = value to build a map instead of a list. [key] += value adds to the value already stored under that key."},{"p":"luwu/table-comprehensions.html#destructuring-items","k":"section","c":"const people = { { name = \"Ada\", age = 36 }, { name = \"Tom\", age = 12 }, } const adults = { for _, .{ name, age } in people when age >= 18 give name } print(adults[1], #adults)","t":"Destructuring items","g":"Table Comprehensions","x":"The loop header can destructure each item."},{"p":"luwu/table-comprehensions.html#several-loops","k":"section","c":"const grid = { { 1, 0, 2 }, { 0, 3, 0 }, } const filled = { for _, row in grid for _, cell in row when cell ~= 0 give cell } print(#filled)","t":"Several loops","g":"Table Comprehensions","x":"Chain for clauses to loop inside a loop. This flattens a grid into a list:"},{"p":"luwu/table-comprehensions.html#items-that-need-statements","k":"section","c":"const lines = { \"hp=10\", \"\", \"mp=4\" } const settings = { for _, line in lines when line ~= \"\" give do const key, value = string.match(line, \"^(%a+)=(%d+)$\") give `{key}: {value}` } print(settings[1], settings[2])","t":"Items that need statements","g":"Table Comprehensions","x":"When one item takes a few steps, give a do expression."},{"p":"luwu/table-comprehensions.html#things-to-know","k":"section","t":"Things to know","g":"Table Comprehensions","x":"A comprehension must be the only thing inside its braces. If an item is nil, nothing is added. Lists never get holes. Numeric loops work too: { for i = 1, 10 give i * i } . Luau's table.insert loop still works. Comprehensions are just shorter."},{"p":"luwu/default-arguments.html","k":"page","c":"local function greet(name: string, greeting: string?) local actual = greeting or \"Hello\" print(`{actual}, {name}!`) end greet(\"Ada\") const function greet(name: string, greeting = \"Hello\") print(`{greeting}, {name}!`) end greet(\"Ada\") greet(\"Grace\", \"Welcome\")","t":"Default Arguments","g":"Default Arguments","x":"Function parameters and class constructor parameters can have default values, and callers can leave those arguments out. In Luau, you'd fill in missing arguments by hand: In Luwu, the default goes in the signature: Inside the function, greeting is always a string. It can never be nil. Your editor shows the default when you call the function."},{"p":"luwu/default-arguments.html#passing-nil","k":"section","c":"const function spawn(kind: string, count = 1, level = 1) print(`{count} x {kind} at level {level}`) end spawn(\"slime\") spawn(\"slime\", nil, 5) const function configure(verbose = true) print(verbose) end configure(false)","t":"Passing nil","g":"Default Arguments","x":"Passing nil is the same as leaving the argument out. That lets you skip one argument and pass the next. Unlike x or default , a default argument doesn't replace false by mistake."},{"p":"luwu/default-arguments.html#defaults-run-on-every-call","k":"section","c":"const function new_inventory(items: { string } = {}) return items end const first = new_inventory() const second = new_inventory() table.insert(first, \"sword\") print(#first, #second) local next_id = 0 const function make_id(): number next_id += 1 return next_id end const function create_user(name: string, id = make_id()) return { name = name, id = id } end print(create_user(\"Ada\").id, create_user(\"Grace\").id, create_user(\"Alan\", 99).id)","t":"Defaults run on every call","g":"Default Arguments","x":"A default is evaluated each time the function needs it. Every call gets its own fresh value. A default can be any expression, including a function call:"},{"p":"luwu/default-arguments.html#classes","k":"section","c":"class Enemy(name: string, hp = 100, speed = 1.0) function describe(self): string return `{self.name}: {self.hp} hp, speed {self.speed}` end end print(Enemy(\"Slime\", 20):describe()) print(Enemy(\"Dragon\", 5000, 0.5):describe())","t":"Classes","g":"Default Arguments","x":"A class's primary constructor takes defaults too:"},{"p":"luwu/default-arguments.html#things-to-know","k":"section","t":"Things to know","g":"Default Arguments","x":"A default can't refer to the other parameters. It sees the variables around the function. Parameters without defaults may come after ones with defaults. To callers, function f(x = 1) takes an optional number."},{"p":"luwu/library-extensions.html","k":"page","t":"Library Extensions","g":"Library Extensions","x":"Luwu's standard library is Luau's plus a few additions that fix real problems."},{"p":"luwu/library-extensions.html#table-drop","k":"section","t":"table.drop","g":"Library Extensions","x":"table.drop removes items from a list by value. It returns how many it removed. It exists to fix one of Luau's most common bugs."},{"p":"luwu/library-extensions.html#the-table-remove-footgun","k":"section","c":"local party = { \"Ada\", \"Grace\", \"Alan\" } table.remove(party, table.find(party, \"Linus\")) print(#party, party[3]) -- 2, nil","t":"The table.remove footgun","g":"Library Extensions","x":"Luau added table.find to get the index of a value in a list. Pairing it with table.remove looks like the obvious way to remove a value: table.find gives nil for Linus, who isn't in the party. Given nil as its index, table.remove removes the last item instead. Alan is gone, and nothing reports an error. The bug only shows up when the value is missing. That makes it easy to miss in testing. Luau doesn't warn about it. The safe version needs an if around every removal."},{"p":"luwu/library-extensions.html#removing-by-value","k":"section","c":"const party = { \"Ada\", \"Grace\", \"Alan\" } print(table.drop(party, \"Linus\"), #party) print(table.drop(party, \"Grace\"), #party) const inventory = { \"sword\", \"potion\" } if table.drop(inventory, \"key\") == 0 then print(\"You don't have a key.\") end const queue = { \"retry\", \"retry\", \"retry\", \"done\" } table.drop(queue, \"retry\", 2) print(#queue, queue[1], queue[2])","t":"Removing by value","g":"Library Extensions","x":"table.drop takes the value itself. A missing value removes nothing: The return value says how many items were removed. Check it when a missing value matters: By default, every match is removed. Pass a count to remove only the first few:"},{"p":"luwu/library-extensions.html#the-lint","k":"section","c":"If this is `nil`, `table.remove` will remove the last element of the array. Consider using `table.drop` instead. If order is not important, use a key/value table for better performance.","t":"The lint","g":"Library Extensions","x":"Luwu also warns when table.remove gets an index that might be nil. The old pattern is underlined with this message: Passing nil on purpose, like table.remove(t, nil) , doesn't warn."},{"p":"luwu/library-extensions.html#things-to-know","k":"section","t":"Things to know","g":"Library Extensions","x":"table.drop compares values like table.find , including __eq . The items after a removed one shift down. The list never gets holes. Dropping from a read-only table is an error. So is a count of zero or less. If order doesn't matter, a set (a table of values mapped to true) removes faster."},{"p":"luwu/library-extensions.html#buffer-isfrozen","k":"section","c":"const bytes = buffer.create(8) buffer.writeu8(bytes, 0, 255) print(buffer.isfrozen(bytes))","t":"buffer.isfrozen","g":"Library Extensions","x":"Programs that embed Luwu can hand it read-only buffers. buffer.isfrozen tells you whether a buffer is one of them. Writing to a frozen buffer is an error. Buffers you create in Luwu are never frozen: Only the runtime can freeze a buffer, by creating it as a read-only external buffer."},{"p":"luwu/library-extensions.html#the-class-library","k":"section","t":"The class library","g":"Library Extensions","x":"The class library works with classes and objects: class.isinstance(value, Class) checks whether a value is an object of a class. class.implements(value, Trait) checks whether its class implements a trait. class.of(object) gives an object's class. class.name(Class) gives a class's name. class.fields(object) gives an object's public fields as a table. They're covered with examples on the Classes and Traits page."},{"p":"luwu/library-extensions.html#planned-additions","k":"section","c":"--- Counts every element in the array and hash parts, to get the size of a map-like or struct-like table. table.count<K, V>(t: { read [K]: V }): number --- Copies every element of e onto the end of t, changing t. table.extend<T>(t: { T }, e: { T }) --- A new table with the elements of t, then the elements of e. table.combine<T, U>(t: { read T }, e: { read U }): { T | U } --- An array of the table's keys. table.keys<K, V>(t: { read [K]: V }): { K } --- An array of the table's values. table.values<K, V>(t: { read [K]: V }): { V } --- Whether s starts with prefix. Not pattern aware or unicode aware. string.startswith(s: string, prefix: string): boolean --- Whether s ends with suffix. Not pattern aware or unicode aware. string.endswith(s: string, suffix: string): boolean --- Trims whitespace from the start, the end or both (\"all\", the default). string.trim(s: string, mode: (\"start\" | \"end\" | \"all\")?): string --- Whether s contains substring, without patterns, like string.find(s, substring, 1, true). string.contains(s: string, substring: string): boolean","t":"Planned additions","g":"Library Extensions","x":"We want to add these functions next:"},{"p":"luwu/external-buffers-and-strings.html","k":"page","t":"External Buffers and Strings","g":"External Buffers and Strings","x":"If an embedder wants to expose a 2 GB archive or dozens of 400 MB .flac files to a Luau script, it has to clone the entire file in memory. In Luwu, it can use an external buffer instead. External buffers and strings are backed by embedder-defined memory, but work seamlessly with the existing buffer and string libraries. Like regular buffers, external buffers are mutable by default. Like regular strings, external strings are always immutable."},{"p":"luwu/external-buffers-and-strings.html#external-buffers","k":"section","t":"External buffers","g":"External Buffers and Strings","x":"An external buffer is a regular buffer whose bytes live in host memory. The whole buffer library works on it, including the native code fast paths. Wrapping host data in a userdata instead would lose all of that. seal uses them for bytes it builds in Rust, like archive contents and websocket frames. The Rust allocation becomes the buffer, instead of being copied into one."},{"p":"luwu/external-buffers-and-strings.html#frozen-buffers","k":"section","c":"const function patch(bytes: buffer, offset: number, value: number) if buffer.isfrozen(bytes) then error(\"this buffer is read-only\") end buffer.writeu8(bytes, offset, value) end const bytes = buffer.create(4) patch(bytes, 0, 42) print(buffer.readu8(bytes, 0))","t":"Frozen buffers","g":"External Buffers and Strings","x":"The host decides whether scripts may write to an external buffer. A read-only one is frozen. Writing to it is an error. That makes it safe to share memory the host must not see change, like a reference-counted file. Scripts check with buffer.isfrozen :"},{"p":"luwu/external-buffers-and-strings.html#the-c-api","k":"section","c":"#define LUA_BLUAU 0 #define LUA_BHOST_IMMUTABLE 1 #define LUA_BHOST_MUTABLE 2 typedef void (*lua_BufferFree)(lua_State* L, void* data, size_t sz, void* userdata); LUA_API void* lua_newexternalbuffer( lua_State* L, size_t sz, void* data, void* userdata, lua_BufferFree free_cb, int mode); LUA_API int lua_getbuffermode(lua_State* L, int idx); LUA_API void* lua_getbufferuserdata(lua_State* L, int idx);","t":"The C API","g":"External Buffers and Strings","x":"lua_newexternalbuffer wraps sz bytes at data . The mode is LUA_BHOST_MUTABLE or LUA_BHOST_IMMUTABLE (frozen). free_cb is optional. The VM calls it with userdata when the buffer is collected. lua_getbuffermode gives a buffer's mode. Buffers made by lua_newbuffer are LUA_BLUAU . lua_getbufferuserdata gives back the userdata pointer, or NULL for a VM buffer. Use it to find your own resource when a script passes the buffer back. From Rust, mluau has create_external_buffer (frozen) and create_external_buffer_mut ."},{"p":"luwu/external-buffers-and-strings.html#external-strings","k":"section","t":"External strings","g":"External Buffers and Strings","x":"An external string is a string whose bytes live in host memory. Scripts can't tell it apart from any other string. It works with the string library, concatenation, and string patterns. It can be a table key. It compares equal to the same text made any other way. Use one when a script expects a string, not a buffer. Error tracebacks, file contents and strings inside JSON are all strings by convention. Lua 5.5 has external strings too."},{"p":"luwu/external-buffers-and-strings.html#the-c-api-2","k":"section","c":"typedef void (*lua_StringFree)(lua_State* L, const char* data, size_t sz, void* userdata); LUA_API const char* lua_pushexternalstring( lua_State* L, const char* data, size_t len, void* userdata, lua_StringFree free_cb); LUA_API int lua_isstringexternal(lua_State* L, int idx); LUA_API void* lua_getstringexternaluserdata(lua_State* L, int idx);","t":"The C API","g":"External Buffers and Strings","x":"data must end in a null byte, at data[len] . len doesn't count it. C code reading the string with lua_tostring relies on it. lua_isstringexternal and lua_getstringexternaluserdata find your resource again, like with buffers. From Rust, mluau has create_external_string ."},{"p":"luwu/external-buffers-and-strings.html#interning","k":"section","t":"Interning","g":"External Buffers and Strings","x":"Luwu interns strings: it keeps one copy of each distinct string and compares strings by pointer. External strings are interned like any other. That has two effects on when your memory gets freed: If the VM already has the same text, you get the existing string back. Your free_cb runs before lua_pushexternalstring returns. The VM may keep a string alive after scripts drop it, for example as a fast lookup key. Its free_cb can run later than you expect."},{"p":"luwu/external-buffers-and-strings.html#things-to-know","k":"section","t":"Things to know","g":"External Buffers and Strings","x":"Strings are immutable. Changing the bytes under a live external string is undefined behavior. If the host needs to change shared memory, use a mutable external buffer instead. External buffers and strings are behind the LuwuExternallyManagedBuffers , LuwuBufferIsFrozen and LuwuExternalString flags."},{"p":"luwu/experimental-features.html","k":"page","t":"Experimental Features","g":"Experimental Features","x":"These features work in Luwu today. Their design isn't final yet. Their syntax may change. Prefer the stable features on the other pages for code you'll keep. Your editor reports them as disabled until you turn on their debug flags."},{"p":"luwu/experimental-features.html#push-and-pop-operators","k":"section","c":"local queue = {} queue <+ \"first\" queue <+ \"second\", \"third\" print(#queue) const last = <-queue print(last, #queue) class Inventory(capacity: number) items: { string } = {} function __push(self, ...: string) for _, item in { ... } do if #self.items < self.capacity then table.insert(self.items, item) end end end function __pop(self): string? return table.remove(self.items) end function __len(self): number return #self.items end end const list = {} list <+ \"sword\", \"shield\", \"potion\" const bag = Inventory(2) bag <+ \"sword\", \"shield\", \"potion\" print(#list, #bag) print(<-list, <-bag)","t":"Push and pop operators","g":"Experimental Features","x":"<+ adds values to a container. <- takes the last value back out. They're a standard way to add to and take from any container. They work the way # works on anything that defines __len . On a plain list, they add to and remove from the end: Nil values are skipped and never leave a hole in the array. A class joins in by defining __push and __pop . Then the same operators work on it, with its own rules. This inventory holds at most two items. Code that fills it doesn't need to know that: The pop syntax isn't decided yet. It may change."},{"p":"luwu/experimental-features.html#match-expressions","k":"section","c":"const function describe(count: number): string return match count case 0 then \"none\" case 1 | 2 | 3 then \"a few\" else \"many\" end print(describe(0), describe(2), describe(50))","t":"match expressions","g":"Experimental Features","x":"A match expression picks a value based on what another value looks like. Each case is checked in order. The else arm is required."},{"p":"luwu/experimental-features.html#matching-objects","k":"section","c":"class Circle(radius: number) end class Rect(width: number, height: number) end const function describe(shape: Circle | Rect): string return match shape case is Circle.{ radius } then `circle with radius {radius}` case is Rect.{ width, height } when width == height then `square of {width}` case is Rect.{ width, height } then `{width} by {height} rectangle` else \"unknown shape\" end print(describe(Circle(2)), describe(Rect(3, 3)), describe(Rect(2, 5)))","t":"Matching objects","g":"Experimental Features","x":"case is Class matches objects of a class. Add a pattern to pull out their fields. A case can add when conditions, like if local."}];
